// REQ-044 (P3 item 4, option b — Tech Gate E-3a/E-3c): i18n field-order
// structural defense. Complements the runtime EnumCount completeness loop in
// TestR6P5P6I18n (run_tests.cpp#L7128-7145) by pinning the LocalizedStrings
// field count at COMPILE time and smoke-checking the Korean designated-
// initializer pilot table (src/i18n.cpp kStringsKorean). The X-macro in
// i18n.cpp already guarantees kLocalizedStringsFieldCount == 57 via its own
// static_assert; because that symbol lives in i18n.cpp's anonymous namespace
// (not linkable here), this suite re-derives the count with the SAME sizeof
// technique (E-3c) so a struct edit that bypasses the i18n.cpp assert still
// trips a compile error in the test TU. Get()-switch/EnumCount completeness is
// already covered by TestR6P5P6I18n and is NOT re-asserted here.
namespace {

// Mirror of LocalizedStrings (src/i18n.cpp) — field COUNT and TYPE only. The
// X-macro there generates the real struct; this anonymous-namespace twin exists
// solely so the sizeof-based count below is checked against a struct with an
// identical layout. It must be kept in sync; the static_assert catches drift.
struct Req044LstrMirror {
    // REQ-045 P4-3: 13 OpenAI fields appended (57 -> 70); REQ-045 P4-5
    // (item 3a-2): 6 user-.gguf fields appended (70 -> 76); REQ-047 D2
    // (design §B.3): 1 bundled-duplicate notice body appended (76 -> 77);
    // REQ-047 U1 (designer 164500 §5.3): 1 tray "(미등록)" marker (77 -> 78);
    // REQ-048 R2-D: 17 gguf-manager family fields appended (78 -> 95);
    // REQ-050: 2 dialog OK/Cancel labels (95 -> 97) plus tooltip/repair-
    // transient (97 -> 99) and the merged-manager Hugging Face block
    // (99 -> 107: 2 add-method buttons + 6 HF dialog strings), plus the
    // OpenAI settings cue-banner hints (107 -> 109); REQ-051 (Symptom D):
    // 1 OpenAI settings [삭제] caption (109 -> 110); REQ-UC (260930_0004,
    // update-checker design §12): the 25-string About update zone block
    // (110 -> 135); REQ-MD (D9): the 9-string model-download dialog
    // (135 -> 144 -> 157); v0.10.5 3-theme UI (Antigravity 261104_0001):
    // 4 theme strings appended (157 -> 161: MenuUiTheme + ThemeFluent/
    // ThemeEditorial/ThemeMonolith).
    const wchar_t* f[161];
};

} // namespace

void TestReq044I18nFieldOrder() {
    std::cout << "[RUN] Testing REQ-044 i18n field-order structural defense..." << std::endl;
    const int failures_before = g_failed_count;

    // ---- (a) Compile-time + runtime field-count pin (E-3c) ----
    static_assert(sizeof(Req044LstrMirror) % sizeof(const wchar_t*) == 0,
                  "REQ-044: Req044LstrMirror must be an array of uniform pointers");
    constexpr std::size_t kExpectedFieldCount =
        sizeof(Req044LstrMirror) / sizeof(const wchar_t*);   // == 161
    static_assert(kExpectedFieldCount == 161,
                   "REQ-044/045/047/048/050/051/UC/MD/REQ-060/v0.10.5-theme: LocalizedStrings field count changed - update the "
                   "i18n.cpp X-macro list, the 37 language tables, "
                   "AND this mirror");
    // Read through a volatile so the runtime TEST_CHECK is a genuine runtime
    // comparison (avoids C4127 "conditional expression is constant" under /W4).
    // The static_assert above remains the compile-time guard; these two are the
    // runtime record that the count held.
    volatile std::size_t observed_field_count = kExpectedFieldCount;
    volatile int observed_enum_count = static_cast<int>(StringId::EnumCount);
    TEST_CHECK(observed_field_count == 161,
                "REQ-044/045/047/048/050/051/UC/MD/REQ-060/v0.10.5-theme: LocalizedStrings field count is 161 (X-macro static_assert "
                "in i18n.cpp is the primary guard; this is the runtime record)");
    TEST_CHECK(observed_enum_count == 161,
                "REQ-044/045/047/048/050/051/UC/MD/REQ-060/v0.10.5-theme: StringId::EnumCount is 161 (struct fields == switch cases)");

    // ---- (b) Korean designated-initializer smoke check ----
    // The Korean table was converted to C++20 designated initializers; a wrong
    // field name or order is a compile error in i18n.cpp. These runtime pins
    // prove the resulting mapping returns the SAME user-visible strings the
    // positional aggregate produced (hardcoded expected values, ko).
    const UiLocale initial = I18n::GetCurrentLocale();
    I18n::SetLocale(UiLocale::Korean);
    TEST_CHECK(I18n::Get(StringId::MenuStatusActive) == L"상태: 활성 (F9: 일시 정지)",
               "REQ-044 ko: MenuStatusActive designated-init mapping intact");
    TEST_CHECK(I18n::Get(StringId::AppName) == L"에메발라 챗",
               "REQ-044 ko: AppName designated-init mapping intact");
    TEST_CHECK(I18n::Get(StringId::AutoDetect) == L"자동 감지",
               "REQ-044 ko: AutoDetect designated-init mapping intact");
    TEST_CHECK(I18n::Get(StringId::TooltipUntranslatedAbove).find(L"번역되지 않은") != std::wstring::npos,
               "REQ-044 ko: TooltipUntranslatedAbove (REQ-042 tail field) designated-init mapping intact");
    TEST_CHECK(I18n::Get(StringId::RepairFailedTitle) == L"로컬 번역을 사용할 수 없습니다",
               "REQ-044 ko: RepairFailedTitle (REQ-005 tail field) designated-init mapping intact");
    I18n::SetLocale(initial); // suite-state hygiene

    if (g_failed_count == failures_before) {
        std::cout << "[PASS] REQ-044 i18n field-order structural defense passed." << std::endl;
    } else {
        std::cout << "[FAIL] REQ-044 i18n field-order structural defense: "
                  << (g_failed_count - failures_before) << " check(s) failed." << std::endl;
    }
}

// v0.10.5 3-theme UI (session 261104_0001): per-locale theme coverage pin.
//
// LocalizedStrings carries English DEFAULT member initializers for the four
// theme fields, so a locale table that omits them silently renders English
// while every other string in that locale is translated. This suite makes
// that omission a test failure instead of an invisible regression.
//
// Source-pin style (same read_src/count_occ discipline as TestW5C1C2BrushPins):
// the 37 tables are aggregates in one TU, so their contents are pinned by
// reading src/i18n.cpp as text. The runtime half then proves the strings
// actually reach I18n::Get / GetThemeStrings for every locale, which catches
// the opposite failure mode (a table that lists the designator but is not
// wired into the GetStrings switch).
void TestThemeI18nCoverage() {
    std::cout << "[TEST] v0.10.5 theme i18n per-locale coverage pins" << std::endl;
    const int failures_before = g_failed_count;

    auto read_src = [](const char* rel) {
        std::string out;
        const char* prefixes[] = {"", "../", "../../"};
        for (const char* pre : prefixes) {
            std::ifstream in((std::string(pre) + rel).c_str(), std::ios::binary);
            if (in) {
                out.assign((std::istreambuf_iterator<char>(in)),
                           std::istreambuf_iterator<char>());
                break;
            }
        }
        return out;
    };
    auto count_occ = [](const std::string& hay, const std::string& needle) {
        size_t n = 0, pos = 0;
        while ((pos = hay.find(needle, pos)) != std::string::npos) {
            ++n;
            pos += needle.size();
        }
        return n;
    };

    const std::string src = read_src("src/i18n.cpp");
    if (src.empty()) {
        std::cout << "[SKIP] src/i18n.cpp not resolvable from the test CWD; theme i18n pins skipped."
                  << std::endl;
        return;
    }

    // ---- (a) Every locale table names all four theme fields ----
    // 36 = the 37 tables minus kStringsEnglish, whose struct defaults ARE the
    // English strings (the documented, intended fallback). Korean and the 35
    // other locales must each carry an explicit designator. The struct itself
    // also declares the four members with defaults, so the raw occurrence count
    // in the file is 36 (tables) + 4 (struct declarations) = 40; the per-table
    // count below is what actually matters.
    const char* const kThemeDesignators[] = {
        ".menu_ui_theme = ",
        ".theme_fluent = ",
        ".theme_editorial = ",
        ".theme_monolith = ",
    };
    for (const char* designator : kThemeDesignators) {
        const size_t hits = count_occ(src, designator);
        TEST_CHECK(hits == 36,
                   std::string("v0.10.5 theme i18n: '") + designator +
                       "' appears in exactly 36 locale tables (37 minus English defaults)");
    }

    // The English table is the ONE intentional default-fallback table: it must
    // not carry theme designators, or the "defaults are English" contract that
    // keeps the struct self-documenting would quietly stop being exercised.
    const size_t english_at = src.find("const LocalizedStrings kStringsEnglish = {");
    TEST_CHECK(english_at != std::string::npos,
               "v0.10.5 theme i18n: kStringsEnglish table located");
    if (english_at != std::string::npos) {
        const size_t english_end = src.find("\n};", english_at);
        const std::string english_body = src.substr(english_at, english_end - english_at);
        TEST_CHECK(english_body.find(".menu_ui_theme") == std::string::npos,
                   "v0.10.5 theme i18n: kStringsEnglish keeps the struct defaults (no designators)");
    }

    // ---- (b) Every locale table is a single initializer style ----
    // MSVC C7556 rejects mixing designated and positional initializers in one
    // aggregate, so the theme designators can only exist in a table that is
    // fully designated. Pin the count of designated tables at 36 (Korean + 35)
    // so a future positional table cannot "add" the designators and fail to
    // compile in a confusing place.
    TEST_CHECK(count_occ(src, "const LocalizedStrings kStrings") == 37,
               "v0.10.5 theme i18n: 37 locale tables present");

    // ---- (c) RTL locales carry genuinely RTL theme strings ----
    // Arabic / Persian / Urdu / Hebrew menu_ui_theme must contain at least one
    // code point in the RTL script ranges (U+0590..U+08FF). A mojibake or
    // transliterated entry would pass a naive "non-empty" check but fail here.
    struct RtlProbe { const char* locale; const char* designator; };
    const RtlProbe rtl_probes[] = {
        {"kStringsArabic",  ".menu_ui_theme = L\""},
        {"kStringsPersian", ".menu_ui_theme = L\""},
        {"kStringsUrdu",    ".menu_ui_theme = L\""},
        {"kStringsHebrew",  ".menu_ui_theme = L\""},
    };
    for (const RtlProbe& probe : rtl_probes) {
        const size_t table_at = src.find(std::string("const LocalizedStrings ") + probe.locale + " = {");
        TEST_CHECK(table_at != std::string::npos,
                   std::string("v0.10.5 theme i18n: ") + probe.locale + " table located");
        if (table_at == std::string::npos) continue;
        const size_t table_end = src.find("\n};", table_at);
        const std::string body = src.substr(table_at, table_end - table_at);
        const size_t line_at = body.find(probe.designator);
        TEST_CHECK(line_at != std::string::npos,
                   std::string("v0.10.5 theme i18n: ") + probe.locale + " names .menu_ui_theme");
        if (line_at == std::string::npos) continue;
        const size_t lit_start = line_at + std::string(probe.designator).size();
        const size_t lit_end = body.find('"', lit_start);
        const std::string literal = body.substr(lit_start, lit_end - lit_start);

        // Decode the UTF-8 literal and look for one RTL-range code point.
        bool has_rtl = false;
        for (size_t k = 0; k < literal.size();) {
            const unsigned char lead = static_cast<unsigned char>(literal[k]);
            unsigned int cp = 0;
            size_t len = 1;
            if (lead < 0x80) { cp = lead; len = 1; }
            else if ((lead & 0xE0) == 0xC0) { cp = lead & 0x1F; len = 2; }
            else if ((lead & 0xF0) == 0xE0) { cp = lead & 0x0F; len = 3; }
            else if ((lead & 0xF8) == 0xF0) { cp = lead & 0x07; len = 4; }
            else { cp = 0; len = 1; }
            for (size_t b = 1; b < len && k + b < literal.size(); ++b) {
                cp = (cp << 6) | (static_cast<unsigned char>(literal[k + b]) & 0x3F);
            }
            if (cp >= 0x0590u && cp <= 0x08FFu) { has_rtl = true; break; }
            k += len;
        }
        TEST_CHECK(has_rtl,
                   std::string("v0.10.5 theme i18n: ") + probe.locale +
                       " .menu_ui_theme contains RTL-range characters (U+0590..U+08FF)");
    }

    // ---- (d) Runtime: the strings reach I18n for every locale ----
    // Catches the opposite regression: a table that lists the designators but
    // is not wired into the GetStrings switch would still fall back to English.
    const UiLocale initial = I18n::GetCurrentLocale();
    const UiLocale locales[] = {
        UiLocale::Korean, UiLocale::English, UiLocale::Vietnamese, UiLocale::ChineseSimplified,
        UiLocale::ChineseTraditional, UiLocale::Japanese, UiLocale::Spanish, UiLocale::French,
        UiLocale::German, UiLocale::Russian, UiLocale::Thai, UiLocale::Arabic,
        UiLocale::Portuguese, UiLocale::Italian, UiLocale::Indonesian, UiLocale::Malay,
        UiLocale::Filipino, UiLocale::Khmer, UiLocale::Lao, UiLocale::Hindi,
        UiLocale::Bengali, UiLocale::Turkish, UiLocale::Polish, UiLocale::Dutch,
        UiLocale::Ukrainian, UiLocale::Persian, UiLocale::Urdu, UiLocale::Hebrew,
        UiLocale::Czech, UiLocale::Hungarian, UiLocale::Swedish, UiLocale::Greek,
        UiLocale::Romanian, UiLocale::Danish, UiLocale::Finnish, UiLocale::Norwegian,
        UiLocale::Burmese,
    };
    int non_english_theme_bundles = 0;
    for (UiLocale loc : locales) {
        I18n::SetLocale(loc);
        const I18nStrings bundle = I18n::GetThemeStrings();
        TEST_CHECK(!bundle.menu_ui_theme.empty() && !bundle.theme_fluent.empty() &&
                       !bundle.theme_editorial.empty() && !bundle.theme_monolith.empty(),
                   std::string("v0.10.5 theme i18n: ") + I18n::LocaleToString(loc) +
                       " yields a non-empty theme bundle");
        TEST_CHECK(I18n::Get(StringId::MenuUiTheme) == bundle.menu_ui_theme,
                   std::string("v0.10.5 theme i18n: ") + I18n::LocaleToString(loc) +
                       " MenuUiTheme matches GetThemeStrings (one lookup path)");
        if (loc != UiLocale::English &&
            bundle.menu_ui_theme != L"UI Theme") {
            ++non_english_theme_bundles;
        }
    }
    // 36 locales (all but English) must differ from the struct default.
    TEST_CHECK(non_english_theme_bundles == 36,
               "v0.10.5 theme i18n: 36 non-English locales have a translated menu_ui_theme");

    // Spot-pin one RTL locale end to end: the runtime value must equal the
    // literal the source pin above validated, proving no reordering happened.
    I18n::SetLocale(UiLocale::Arabic);
    TEST_CHECK(I18n::Get(StringId::MenuUiTheme) == L"سمة الواجهة",
               "v0.10.5 theme i18n: ar MenuUiTheme runtime value intact");
    I18n::SetLocale(UiLocale::Hebrew);
    TEST_CHECK(I18n::Get(StringId::ThemeMonolith) == L"ריפיינד מונוליט",
               "v0.10.5 theme i18n: he ThemeMonolith runtime value intact");
    I18n::SetLocale(initial); // suite-state hygiene

    if (g_failed_count == failures_before) {
        std::cout << "[PASS] v0.10.5 theme i18n per-locale coverage pins passed." << std::endl;
    } else {
        std::cout << "[FAIL] v0.10.5 theme i18n per-locale coverage pins: "
                  << (g_failed_count - failures_before) << " check(s) failed." << std::endl;
    }
}

// REQ-045 P4-8 (item 1, design §B + Tech Gate Item 6): structural pins for
// the "local engine unavailable" modal helper and the SEC-ADJ (0,0) marshal
// seam in main.cpp. main.cpp is the GUI entrypoint TU and is deliberately
// NOT linked into run_tests.exe (per the SEC-B5 note in main.cpp itself), so
// the security property (no heap pointer crosses PostMessageW) and the
// trigger wiring are pinned by source inspection, following the TestReq042
// structural-pin precedent.
void TestReq045EngineUnavailableModal() {
    std::cout << "[TEST] REQ-045 P4-8 engine-unavailable modal structural pins..." << std::endl;
    const int failures_before = g_failed_count;

    auto read_src = [](const char* name, std::string& out) {
        const char* candidates[] = {name, (std::string("../") + name).c_str(),
                                    (std::string("../../") + name).c_str()};
        for (const char* cand : candidates) {
            std::ifstream in(cand, std::ios::binary);
            if (in) {
                out.assign((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
                return;
            }
        }
    };
    std::string main_src;
    read_src("src/main.cpp", main_src);
    if (main_src.empty()) {
        std::cout << "[SKIP] src/main.cpp not resolvable from the test CWD; REQ-045 P4-8 pins skipped."
                  << std::endl;
        return;
    }

    // The modal helper exists and is called from both trigger sites.
    TEST_CHECK(main_src.find("ShowLocalEngineUnavailableModal") != std::string::npos,
               "REQ-045 P4-8 structural pin: ShowLocalEngineUnavailableModal helper defined in main.cpp");
    TEST_CHECK(main_src.find("RequestEngineUnavailableModal") != std::string::npos,
               "REQ-045 P4-8 structural pin: RequestEngineUnavailableModal marshal seam defined in main.cpp");

    // The CheckComponents call site fires on the local-LLM tray pick.
    TEST_CHECK(main_src.find("bs::CheckComponents()") != std::string::npos,
               "REQ-045 P4-8 structural pin: CheckComponents() called from the tray on_select_engine path");

    // SEC-ADJ (Tech Gate Item 6): the modal marshal posts a PURE (0,0) wake-up
    // — no heap pointer in LPARAM. Pin the exact PostMessageW call shape.
    TEST_CHECK(main_src.find("PostMessageW(hController, kMsgEngineUnavailableModal, 0, 0)") != std::string::npos,
               "REQ-045 P4-8 SEC-ADJ pin: the modal marshal posts a pure (0,0) wake-up — no heap pointer in LPARAM");

    // The modal uses MB_OK|MB_ICONINFORMATION|MB_TOPMOST (A1: no auto-dismiss,
    // A3: explicit close, mirrors the P4-5 quality-gate TOPMOST policy).
    TEST_CHECK(main_src.find("MB_OK | MB_ICONINFORMATION | MB_TOPMOST") != std::string::npos,
               "REQ-045 P4-8 structural pin: modal is MB_OK|MB_ICONINFORMATION|MB_TOPMOST (no auto-dismiss)");

    if (g_failed_count == failures_before) {
        std::cout << "[PASS] REQ-045 P4-8 engine-unavailable modal structural pins passed." << std::endl;
    } else {
        std::cout << "[FAIL] REQ-045 P4-8 engine-unavailable modal structural pins: "
                  << (g_failed_count - failures_before) << " check(s) failed." << std::endl;
    }
}

// REQ-046 P4-2 (Rev2 §B-4 + §C-1, Ask Light Gate C1): functional pins for the
// host's boot-time config reader. The reader was extracted to
// engine_host_config_reader.cpp (Emebalachat_core) precisely so this suite can
// link it (Debug Tech Gate §2 조건-1). INV-B1b is the C1 headline: a stale
// user_model_id persisted under engine_type="local" must NOT reach the host
// cache — the pinned Hy-MT2 path has to keep serving.
void TestReq046HostUserModelIdGate() {
    std::cout << "[TEST] REQ-046 P4-2 host user_model_id C1 gate (INV-B1b~B1g)..." << std::endl;
    const int failures_before = g_failed_count;

    namespace fs = std::filesystem;
    std::error_code ec;
    // Fixture-hygiene guard: if the temp root cannot be prepared, every
    // check below would be meaningless — count ONE failure and bail.
    auto fixture_fail = [&]() {
        TEST_CHECK(false, "REQ-046 fixture: temp config directory unavailable");
    };
    const fs::path root = fs::temp_directory_path(ec) / L"emebala_req046_gate_test";
    if (ec) { fixture_fail(); return; }
    fs::remove_all(root, ec); // clean slate (also clears stale leftovers)
    ec.clear();
    fs::create_directories(root / L"Emebalachat", ec);
    if (ec) { fixture_fail(); return; }
    const std::wstring lad = root.wstring();

    auto write_config = [&](const std::string& body) {
        std::ofstream out(root / L"Emebalachat" / L"config.json",
                          std::ios::binary | std::ios::trunc);
        if (!out.is_open()) { fixture_fail(); return false; }
        out << body;
        out.close();
        if (!out) { fixture_fail(); return false; }
        return true;
    };

    // INV-B1b (C1 headline): "local" + a stale user_model_id -> "" so the
    // pinned Hy-MT2 path serves (the user's "터치하면 안 됨" contract).
    write_config("{\"engine_type\": \"local\", \"user_model_id\": \"user-test\"}");
    TEST_CHECK(enginehost::LoadUserModelIdFromConfig(lad).empty(),
               "INV-B1b: engine_type=local + user_model_id set -> \"\" (pinned Hy-MT2 serves)");

    // INV-B1c: "user_gguf" + id -> the id is cached.
    write_config("{\"engine_type\": \"user_gguf\", \"user_model_id\": \"user-test\"}");
    TEST_CHECK(enginehost::LoadUserModelIdFromConfig(lad) == "user-test",
               "INV-B1c: engine_type=user_gguf -> user_model_id returned");

    // INV-B1d: "user_gguf" + empty id -> "" (nothing to relay).
    write_config("{\"engine_type\": \"user_gguf\", \"user_model_id\": \"\"}");
    TEST_CHECK(enginehost::LoadUserModelIdFromConfig(lad).empty(),
               "INV-B1d: engine_type=user_gguf + empty id -> \"\"");

    // INV-B1e: engine_type ABSENT -> "" (a pre-REQ-046 config can never arm
    // the user-model relay).
    write_config("{\"user_model_id\": \"user-test\"}");
    TEST_CHECK(enginehost::LoadUserModelIdFromConfig(lad).empty(),
               "INV-B1e: engine_type absent -> \"\"");

    // INV-B1f: any other engine_type ("google" here; "auto"/unknown share the
    // path) -> "".
    write_config("{\"engine_type\": \"google\", \"user_model_id\": \"user-test\"}");
    TEST_CHECK(enginehost::LoadUserModelIdFromConfig(lad).empty(),
               "INV-B1f: engine_type=google -> \"\"");

    // INV-B1g: config.json itself ABSENT -> "" (pre-existing behavior).
    fs::remove(root / L"Emebalachat" / L"config.json", ec);
    ec.clear();
    TEST_CHECK(enginehost::LoadUserModelIdFromConfig(lad).empty(),
               "INV-B1g: config.json absent -> \"\"");

    // user_gguf round-trip through the REAL AppConfig persistence path
    // (SaveToFile/LoadFromFile) — proves the app's own writer emits the two
    // keys the host's minimal parser reads back.
    {
        AppConfig cfg;
        cfg.SetEngineTypeName("user_gguf");
        cfg.SetUserModelId("user-roundtrip");
        const fs::path cfg_path = root / L"roundtrip.json";
        if (!cfg.SaveToFile(cfg_path)) {
            fixture_fail();
        } else {
            AppConfig re;
            if (!re.LoadFromFile(cfg_path)) {
                fixture_fail();
            } else {
                // user_model_id is a direct field (deliberately no Snapshot
                // entry — never read by the hook/worker threads, config.hpp).
                TEST_CHECK(re.GetSnapshot().engine_type == "user_gguf" &&
                           re.user_model_id == "user-roundtrip",
                           "user_gguf round-trip: AppConfig persists + reloads engine_type/user_model_id");
                // The reader only reads <lad>/Emebalachat/config.json, so a
                // sibling file must stay unread (canonical name only).
                TEST_CHECK(enginehost::LoadUserModelIdFromConfig(lad).empty(),
                           "reader: unrelated config path in the lad root stays unread (canonical name only)");
                // Stage the round-tripped file at the canonical spot to
                // assert the writer's output is parse-compatible with the
                // reader.
                fs::copy_file(cfg_path, root / L"Emebalachat" / L"config.json",
                              fs::copy_options::overwrite_existing, ec);
                if (ec) {
                    fixture_fail();
                    ec.clear();
                } else {
                    TEST_CHECK(enginehost::LoadUserModelIdFromConfig(lad) == "user-roundtrip",
                               "user_gguf round-trip: the reader parses AppConfig's own serialized output");
                    fs::remove(root / L"Emebalachat" / L"config.json", ec);
                    ec.clear();
                }
            }
        }
    }

    // Unknown engine_type + user_model_id -> "" (the fallback policy: any
    // value outside the exact "user_gguf" keeps the pinned path).
    write_config("{\"engine_type\": \"something_new\", \"user_model_id\": \"user-test\"}");
    TEST_CHECK(enginehost::LoadUserModelIdFromConfig(lad).empty(),
               "unknown engine_type -> \"\" (fallback to pinned path)");

    fs::remove_all(root, ec);
    if (g_failed_count == failures_before) {
        std::cout << "[PASS] REQ-046 P4-2 host user_model_id C1 gate passed." << std::endl;
    } else {
        std::cout << "[FAIL] REQ-046 P4-2 host user_model_id C1 gate: "
                  << (g_failed_count - failures_before) << " check(s) failed." << std::endl;
    }
}

// REQ-060 F-09 fix (session 261009_0001, fix-policy-precedence round): the
// pin-resolution precedence is HOST-side logic inside host_main.cpp's
// anonymous namespace (that TU is the EmebalaEngine exe, NOT linked into
// run_tests), so the three-layer contract — client policy model_id (REQ-CP T3)
// > explicit per-request id (v1 wire member / v2 session model) > the
// identity-gated relay fallback — is pinned here as SOURCE pins, exactly like
// the req055/req058 host_main.cpp pins. The pure policy MERGE layer
// (MergeForRequest, request-wins) is a different function with its own suite
// and is intentionally NOT covered here.
void TestReq060PinPrecedence() {
    std::cout << "[TEST] REQ-060 F-09 pin precedence source pins..." << std::endl;
    const int failures_before = g_failed_count;

    const std::filesystem::path host_main = ResolveRepoFile(L"src\\host_main.cpp");
    if (host_main.empty()) {
        std::cout << "[SKIP] src/host_main.cpp not resolvable; REQ-060 F-09 pins skipped."
                  << std::endl;
    } else {
        std::ifstream in(host_main, std::ios::binary);
        const std::string src((std::istreambuf_iterator<char>(in)),
                              std::istreambuf_iterator<char>());

        // (1) The single resolver exists; inside its body the policy check
        //     PRECEDES the explicit-id check, which precedes the relay fallback.
        const size_t helper_pos = src.find("ResolveTranslatePin(const std::string& client");
        TEST_CHECK(helper_pos != std::string::npos,
                   "REQ-060 F-09: ResolveTranslatePin exists in host_main.cpp");
        if (helper_pos != std::string::npos) {
            const size_t helper_end = src.find("\n}\n", helper_pos);
            const std::string body = src.substr(
                helper_pos, helper_end == std::string::npos ? std::string::npos
                                                            : helper_end - helper_pos);
            const size_t policy_pos = body.find("!policy.model_id.empty()");
            const size_t explicit_pos = body.find("!explicit_model_id.empty()");
            const size_t fallback_pos = body.find("return RelayPinForClient(client)");
            TEST_CHECK(policy_pos != std::string::npos &&
                           explicit_pos != std::string::npos &&
                           fallback_pos != std::string::npos,
                       "REQ-060 F-09: resolver body carries all three layers");
            TEST_CHECK(policy_pos < explicit_pos && explicit_pos < fallback_pos,
                       "REQ-060 F-09: order is policy > explicit > relay fallback");
            TEST_CHECK(body.find("LoadClientPolicyLive(client") != std::string::npos,
                       "REQ-060 F-09: the policy layer rides the T2 live reader");
        }

        // (2) Every translate path resolves through the helper (no dispatcher
        //     re-implements the ternary).
        const size_t v1_pos = src.find("void DispatcherLoop(host_v2::WorkerManager& wmgr)");
        const size_t v2_pos = src.find("void DispatcherV2Loop(host_v2::WorkerManager& wmgr)");
        TEST_CHECK(v1_pos != std::string::npos && v2_pos != std::string::npos,
                   "REQ-060 F-09: both dispatcher loops located for the call-site pins");
        if (v1_pos != std::string::npos) {
            const std::string v1_region = src.substr(
                v1_pos, v2_pos == std::string::npos ? std::string::npos : v2_pos - v1_pos);
            TEST_CHECK(v1_region.find("ResolveTranslatePin(job.client, job.model_id)") !=
                           std::string::npos,
                       "REQ-060 F-09: the v1 dispatcher resolves via the helper");
            TEST_CHECK(v1_region.find("job.model_id.empty() ? RelayPinForClient") ==
                           std::string::npos,
                       "REQ-060 F-09: the v1 loop has no leftover explicit-first ternary");
        }
        if (v2_pos != std::string::npos) {
            TEST_CHECK(src.find("ResolveTranslatePin(item.client, explicit_model_id)",
                                v2_pos) != std::string::npos,
                       "REQ-060 F-09: the v2 dispatcher resolves via the helper "
                       "(session model as the explicit id)");
        }
        TEST_CHECK(src.find("ResolveTranslatePin(hello.client, \"\")") != std::string::npos,
                   "REQ-060 F-09: the warmup registration resolves the hold family "
                   "through the helper (relay fallback layer)");
        TEST_CHECK(src.find("ResolveTranslatePin(conn.client, msg.model_id)") !=
                       std::string::npos,
                   "REQ-060 F-09: the v1 fast-path probe resolves via the helper, "
                   "so the probe verdict and the served model cannot diverge");

        // (3) Global negative pin: the F-09 violation shape (explicit id tested
        //     before the policy) must not survive anywhere in the file.
        TEST_CHECK(src.find("model_id.empty() ? RelayPinForClient") == std::string::npos,
                   "REQ-060 F-09: no explicit-first pin ternary remains in host_main.cpp");
    }

    if (g_failed_count == failures_before) {
        std::cout << "[PASS] REQ-060 F-09 pin precedence pins passed." << std::endl;
    } else {
        std::cout << "[FAIL] REQ-060 F-09 pin precedence: "
                  << (g_failed_count - failures_before) << " check(s) failed." << std::endl;
    }
}

// REQ-060 (session 261009_0001): the HOST-side boot read of
// engine_host.worker_idle_ms. The host reads the SAME nested block the app's
// config.cpp ParseEngineHostBlock writes; the clamp discipline must match the
// client parser exactly (<=0 -> 90000, <5000 -> 5000, >86400000 -> 86400000,
// absent / wrong-typed / unparseable -> 90000).
void TestReq060HostBootWorkerIdleMs() {
    std::cout << "[TEST] REQ-060 host boot worker_idle_ms parse/clamp..." << std::endl;
    const int failures_before = g_failed_count;
    namespace fs = std::filesystem;
    std::error_code ec;
    auto fixture_fail = [&]() {
        TEST_CHECK(false, "REQ-060 fixture: temp config directory unavailable");
    };
    const fs::path root = fs::temp_directory_path(ec) / L"emebala_req060_idle_test";
    if (ec) { fixture_fail(); return; }
    fs::remove_all(root, ec); // clean slate (also clears stale leftovers)
    ec.clear();
    fs::create_directories(root / L"Emebalachat", ec);
    if (ec) { fixture_fail(); return; }
    const std::wstring lad = root.wstring();

    auto write_config = [&](const std::string& body) {
        std::ofstream out(root / L"Emebalachat" / L"config.json",
                          std::ios::binary | std::ios::trunc);
        if (!out.is_open()) { fixture_fail(); return false; }
        out << body;
        out.close();
        if (!out) { fixture_fail(); return false; }
        return true;
    };

    // Absent engine_host block -> the 90000 default.
    write_config("{\"engine_type\": \"local\"}");
    TEST_CHECK(enginehost::LoadHostBootConfig(lad).worker_idle_ms == 90000,
               "REQ-060: absent engine_host block -> 90000");

    // In-range value kept verbatim.
    write_config("{\"engine_host\": {\"worker_idle_ms\": 30000}}");
    TEST_CHECK(enginehost::LoadHostBootConfig(lad).worker_idle_ms == 30000,
               "REQ-060: in-range worker_idle_ms kept (30000)");

    // 0 / negative -> the 90000 default policy.
    write_config("{\"engine_host\": {\"worker_idle_ms\": 0}}");
    TEST_CHECK(enginehost::LoadHostBootConfig(lad).worker_idle_ms == 90000,
               "REQ-060: worker_idle_ms 0 -> 90000");
    write_config("{\"engine_host\": {\"worker_idle_ms\": -5}}");
    TEST_CHECK(enginehost::LoadHostBootConfig(lad).worker_idle_ms == 90000,
               "REQ-060: worker_idle_ms negative -> 90000");

    // Below the 5 s floor -> clamped up.
    write_config("{\"engine_host\": {\"worker_idle_ms\": 3000}}");
    TEST_CHECK(enginehost::LoadHostBootConfig(lad).worker_idle_ms == 5000,
               "REQ-060: worker_idle_ms 3000 -> 5000 (floor)");

    // Above the 24 h ceiling -> clamped down.
    write_config("{\"engine_host\": {\"worker_idle_ms\": 99999999999}}");
    TEST_CHECK(enginehost::LoadHostBootConfig(lad).worker_idle_ms == 86400000,
               "REQ-060: worker_idle_ms 99999999999 -> 86400000 (ceiling)");

    // Wrong-typed (string) / unparseable literal -> the default.
    write_config("{\"engine_host\": {\"worker_idle_ms\": \"30000\"}}");
    TEST_CHECK(enginehost::LoadHostBootConfig(lad).worker_idle_ms == 90000,
               "REQ-060: string-typed worker_idle_ms -> 90000");
    write_config("{\"engine_host\": {\"worker_idle_ms\": abc}}");
    TEST_CHECK(enginehost::LoadHostBootConfig(lad).worker_idle_ms == 90000,
               "REQ-060: unparseable worker_idle_ms -> 90000");

    // Absent key inside the block -> the default; the sibling keys the app
    // writes must not disturb the read.
    write_config("{\"engine_host\": {\"enabled\": true, \"spawn\": true, "
                 "\"idle_exit_ms\": 600000, \"warmup\": false}}");
    TEST_CHECK(enginehost::LoadHostBootConfig(lad).worker_idle_ms == 90000,
               "REQ-060: block present, key absent -> 90000");

    // Regression guard: the pre-REQ-060 HostBootConfig fields keep parsing
    // alongside the new key (one parse feeds all three).
    write_config("{\"engine_type\": \"user_gguf\", \"user_model_id\": \"user-060\", "
                 "\"diag_log_enabled\": true, "
                 "\"engine_host\": {\"worker_idle_ms\": 45000}}");
    {
        const enginehost::HostBootConfig cfg = enginehost::LoadHostBootConfig(lad);
        TEST_CHECK(cfg.worker_idle_ms == 45000 && cfg.diag_log_enabled &&
                       cfg.user_model_id == "user-060",
                   "REQ-060: worker_idle_ms + diag_log_enabled + user_model_id read in ONE parse");
    }

    fs::remove_all(root, ec);
    if (g_failed_count == failures_before) {
        std::cout << "[PASS] REQ-060 host boot worker_idle_ms parse/clamp passed." << std::endl;
    } else {
        std::cout << "[FAIL] REQ-060 host boot worker_idle_ms parse/clamp: "
                  << (g_failed_count - failures_before) << " check(s) failed." << std::endl;
    }
}

// REQ-060 (session 261009_0001, host-fix round per dispute-verification
// 261009_0001): the orchestrator-side idle eviction + warmup hold pins. The
// eviction drives the GENUINE reaper path (worker-thread connect+announce
// reaches Ready through FakeHandshakeSpawn, exactly like the B-T3 tracker
// pins): Ready + idle-past-budget + policy "evict" + no warmup hold -> the
// pass claims the family (Stopping -> M-2 GracefulStop -> Stopped) and resets
// the pool entry's accounting. The pool NODE survives the eviction (the UAF
// fix: it is never erased at runtime — dispatchers hold its pointer across a
// whole job). The fake process handle is a live event (never signaled), so
// each real eviction costs one GracefulStop kill-escalation window (~2 s) —
// the suite plans its evictions accordingly.
void TestReq060WorkerIdleEviction() {
    std::cout << "[RUN] Testing REQ-060 worker idle eviction + warmup holds..." << std::endl;
    const int failures_before = g_failed_count;
    namespace hv2 = emebalachat::host_v2;
    namespace detail = translate_pool_test_detail;

    const wchar_t* kTranslateFamily = L"ggml-translate";
    const unsigned long long kMiB = 1024ull * 1024;
    wchar_t self[MAX_PATH] = {0};
    ::GetModuleFileNameW(nullptr, self, MAX_PATH); // a guaranteed-present exe path
    auto test_now_ms = []() -> int64_t {
        return std::chrono::duration_cast<std::chrono::milliseconds>(
                   std::chrono::steady_clock::now().time_since_epoch()).count();
    };

    // ---- 1. Ready + idle + "evict" -> GracefulStop + accounting reset -------
    //         (the pool node survives)
    {
        detail::FakeHandshakeCtx ctx;
        ctx.exit_ev = ::CreateEventW(nullptr, TRUE, FALSE, nullptr);
        TEST_CHECK(ctx.exit_ev != nullptr, "evict: exit event created");
        hv2::WorkerManager mgr(&detail::FakeHandshakeSpawn, [](HANDLE, void*) {}, &ctx);
        mgr.SetTranslateExePath(self);
        mgr.RegisterFamily(kTranslateFamily, self);
        mgr.RegisterTranslatePoolBootEntry();
        mgr.SetVramBytesResolver([](const std::string&) { return 700ull * kMiB; });
        mgr.SetFreeVramProbe([](unsigned long long& out) { out = 8ull * 1024 * kMiB; return true; });
        mgr.SetWorkerIdleMs(5000);

        hv2::WorkerHandle* w = mgr.EnsureSpawned(kTranslateFamily);
        if (ctx.hs_thread.joinable()) ctx.hs_thread.join();
        TEST_CHECK(w != nullptr && w->state == hv2::WorkerState::Ready,
                   "evict: spawn reached Ready (real connect+announce)");
        TEST_CHECK(mgr.TranslatePoolReservedVramBytes() == 700ull * kMiB,
                   "evict: tracker charged after Ready");
        hv2::TranslatePoolEntry* e = mgr.TranslatePoolEnsure("");
        TEST_CHECK(e != nullptr && e->eviction_policy == "evict",
                   "evict: no resolver -> the default policy is \"evict\"");
        TEST_CHECK(mgr.WorkerIdleMs() == 5000, "evict: the idle budget setter round-trips");

        const int64_t t0 = mgr.Find(kTranslateFamily)->last_activity_ms;
        // Boundary: idle age == budget is NOT past the budget (strictly
        // greater evicts) — the family must survive its exact budget.
        TEST_CHECK(mgr.ReaperPass(t0 + 5000) == 0 &&
                       mgr.State(kTranslateFamily) == hv2::WorkerState::Ready,
                   "evict: idle age == budget survives (not past the budget)");
        // Past the budget: one pass claims, stops and resets the accounting.
        TEST_CHECK(mgr.ReaperPass(t0 + 5001) == 0, "evict: eviction is not a crash");
        TEST_CHECK(mgr.State(kTranslateFamily) == hv2::WorkerState::Stopped,
                   "evict: Ready + idle + evict -> the family is GracefulStopped");
        // REQ-060 UAF fix: the pool node SURVIVES the eviction (never erased at
        // runtime) — a TranslatePoolEntry* taken before the eviction (a
        // dispatcher holds it across a whole job) stays valid, accounting 0.
        TEST_CHECK(mgr.TranslatePoolSize() == 1,
                   "evict: the pool entry SURVIVES the eviction (map node never erased)");
        TEST_CHECK(e != nullptr && e->reserved_vram_bytes == 0,
                   "evict: the pre-eviction entry pointer stays valid; its accounting is reset");
        TEST_CHECK(mgr.TranslatePoolReservedVramBytes() == 0,
                   "evict: the reserved-VRAM contribution is restored exactly");
        // A later request reuses the SAME node (accounting was reset, not
        // erased; the Ready-charge site re-charges when the family respawns).
        hv2::TranslatePoolEntry* e2 = mgr.TranslatePoolEnsure("");
        TEST_CHECK(e2 == e && e2->reserved_vram_bytes == 0 && mgr.TranslatePoolSize() == 1,
                   "evict: re-ensure reuses the SAME entry node (reset, not re-registration)");
        ::CloseHandle(ctx.exit_ev);
    }

    // ---- 2. Busy families are never evicted; the release refreshes the clock
    {
        detail::FakeHandshakeCtx ctx;
        ctx.exit_ev = ::CreateEventW(nullptr, TRUE, FALSE, nullptr);
        TEST_CHECK(ctx.exit_ev != nullptr, "busy: exit event created");
        hv2::WorkerManager mgr(&detail::FakeHandshakeSpawn, [](HANDLE, void*) {}, &ctx);
        mgr.SetTranslateExePath(self);
        mgr.RegisterFamily(kTranslateFamily, self);
        mgr.RegisterTranslatePoolBootEntry();
        mgr.SetVramBytesResolver([](const std::string&) { return 700ull * kMiB; });
        mgr.SetFreeVramProbe([](unsigned long long& out) { out = 8ull * 1024 * kMiB; return true; });
        mgr.SetWorkerIdleMs(5000);

        hv2::WorkerHandle* w = mgr.EnsureSpawned(kTranslateFamily);
        if (ctx.hs_thread.joinable()) ctx.hs_thread.join();
        TEST_CHECK(w != nullptr && w->state == hv2::WorkerState::Ready,
                   "busy: spawn reached Ready");
        const int64_t t0 = mgr.Find(kTranslateFamily)->last_activity_ms;
        TEST_CHECK(mgr.TrySetBusy(kTranslateFamily), "busy: single-flight acquire");
        TEST_CHECK(mgr.ReaperPass(t0 + 60000) == 0 &&
                       mgr.State(kTranslateFamily) == hv2::WorkerState::Busy,
                   "busy: a Busy family is NOT evicted on a far-future pass");
        TEST_CHECK(mgr.TranslatePoolSize() == 1 && mgr.TranslatePoolReservedVramBytes() == 700ull * kMiB,
                   "busy: the pool entry + tracker stay intact while Busy");
        mgr.SetBusy(kTranslateFamily, false);
        const int64_t t1 = mgr.Find(kTranslateFamily)->last_activity_ms;
        TEST_CHECK(t1 >= t0, "busy: job completion refreshed the idle clock");
        TEST_CHECK(mgr.ReaperPass(t1 + 5001) == 0 &&
                       mgr.State(kTranslateFamily) == hv2::WorkerState::Stopped,
                   "busy: once released, the next idle pass evicts normally");
        ::CloseHandle(ctx.exit_ev);
    }

    // ---- 3. "sticky" policy: the reaper never evicts a resident entry -----
    {
        detail::FakeHandshakeCtx ctx;
        ctx.exit_ev = ::CreateEventW(nullptr, TRUE, FALSE, nullptr);
        TEST_CHECK(ctx.exit_ev != nullptr, "sticky: exit event created");
        hv2::WorkerManager mgr(&detail::FakeHandshakeSpawn, [](HANDLE, void*) {}, &ctx);
        mgr.SetTranslateExePath(self);
        mgr.SetEvictionPolicyResolver([](const std::string& id) {
            return id == "zz-sticky" ? std::string("sticky") : std::string("evict");
        });
        mgr.RegisterFamily(kTranslateFamily, self);
        mgr.RegisterTranslatePoolBootEntry();
        mgr.SetVramBytesResolver([](const std::string&) { return 700ull * kMiB; });
        mgr.SetFreeVramProbe([](unsigned long long& out) { out = 8ull * 1024 * kMiB; return true; });
        mgr.SetWorkerIdleMs(5000);

        hv2::TranslatePoolEntry* boot = mgr.TranslatePoolEnsure("");
        TEST_CHECK(boot != nullptr && boot->eviction_policy == "evict",
                   "sticky: the boot \"\" entry resolves \"evict\" through the resolver");
        hv2::TranslatePoolEntry* s = mgr.TranslatePoolEnsure("zz-sticky");
        TEST_CHECK(s != nullptr && s->eviction_policy == "sticky",
                   "sticky: the resolver's \"sticky\" spelling is stored verbatim");
        hv2::WorkerHandle* w = mgr.EnsureSpawned(s->family);
        if (ctx.hs_thread.joinable()) ctx.hs_thread.join();
        TEST_CHECK(w != nullptr && w->state == hv2::WorkerState::Ready,
                   "sticky: spawn reached Ready");
        const int64_t t0 = mgr.Find(s->family)->last_activity_ms;
        TEST_CHECK(mgr.ReaperPass(t0 + 60000) == 0 &&
                       mgr.State(s->family) == hv2::WorkerState::Ready,
                   "sticky: a far-future pass leaves the sticky family Ready");
        TEST_CHECK(mgr.TranslatePoolSize() == 2,
                   "sticky: both pool entries survive (nothing removed)");
        mgr.GracefulStop(*w, 2000); // direct release (the entry itself stays)
        ::CloseHandle(ctx.exit_ev);
    }

    // ---- 4. Warmup holds skip ONLY their family; the last release resets the
    //         family's idle clock ---------------------------------------------
    {
        detail::FakeHandshakeCtx ctx;
        ctx.exit_ev = ::CreateEventW(nullptr, TRUE, FALSE, nullptr);
        TEST_CHECK(ctx.exit_ev != nullptr, "warmup: exit event created");
        hv2::WorkerManager mgr(&detail::FakeHandshakeSpawn, [](HANDLE, void*) {}, &ctx);
        mgr.SetTranslateExePath(self);
        mgr.RegisterFamily(kTranslateFamily, self);
        mgr.RegisterTranslatePoolBootEntry();
        mgr.SetVramBytesResolver([](const std::string&) { return 700ull * kMiB; });
        mgr.SetFreeVramProbe([](unsigned long long& out) { out = 8ull * 1024 * kMiB; return true; });
        mgr.SetWorkerIdleMs(5000);

        hv2::WorkerHandle* w = mgr.EnsureSpawned(kTranslateFamily);
        if (ctx.hs_thread.joinable()) ctx.hs_thread.join();
        TEST_CHECK(w != nullptr && w->state == hv2::WorkerState::Ready,
                   "warmup: spawn reached Ready");
        const int64_t t0 = mgr.Find(kTranslateFamily)->last_activity_ms;

        mgr.RegisterWarmupConnection(kTranslateFamily);
        TEST_CHECK(mgr.WarmupConnectionCount(kTranslateFamily) == 1,
                   "warmup: the hold is tracked");
        TEST_CHECK(mgr.ReaperPass(t0 + 60000) == 0 &&
                       mgr.State(kTranslateFamily) == hv2::WorkerState::Ready,
                   "warmup: a warm-held family is NOT evicted on a far-future pass");
        mgr.RegisterWarmupConnection(kTranslateFamily); // a stacked hold
        TEST_CHECK(mgr.WarmupConnectionCount(kTranslateFamily) == 2 &&
                       mgr.ReaperPass(t0 + 120000) == 0 &&
                       mgr.State(kTranslateFamily) == hv2::WorkerState::Ready,
                   "warmup: stacked holds keep the family alive");

        // The LAST release resets the idle clock: the pre-warmup idle age
        // must not instant-evict the family.
        mgr.UnregisterWarmupConnection(kTranslateFamily);
        TEST_CHECK(mgr.WarmupConnectionCount(kTranslateFamily) == 1,
                   "warmup: one hold remains after the first release");
        const int64_t before_last_release = test_now_ms();
        mgr.UnregisterWarmupConnection(kTranslateFamily);
        TEST_CHECK(mgr.WarmupConnectionCount(kTranslateFamily) == 0,
                   "warmup: the count floors at zero");
        const int64_t t1 = mgr.Find(kTranslateFamily)->last_activity_ms;
        TEST_CHECK(t1 >= before_last_release,
                   "warmup: the last release RESET the family's idle clock");
        TEST_CHECK(mgr.ReaperPass(t1 + 5000) == 0 &&
                       mgr.State(kTranslateFamily) == hv2::WorkerState::Ready,
                   "warmup: the fresh window survives (age == budget)");
        TEST_CHECK(mgr.ReaperPass(t1 + 5001) == 0 &&
                       mgr.State(kTranslateFamily) == hv2::WorkerState::Stopped,
                   "warmup: past the fresh window the family evicts normally");
        // An unbalanced release is a harmless no-op (no count, no crash).
        mgr.UnregisterWarmupConnection(kTranslateFamily);
        TEST_CHECK(mgr.WarmupConnectionCount(kTranslateFamily) == 0,
                   "warmup: an unbalanced release is a no-op");
        ::CloseHandle(ctx.exit_ev);
    }

    // ---- 5. ResetTranslatePoolAccounting: the direct API semantics ----------
    // (replaces the removed RemoveTranslatePoolEntry: the UAF fix keeps the
    // map node alive and only resets the entry's accounting)
    {
        detail::FakeHandshakeCtx ctx;
        ctx.exit_ev = ::CreateEventW(nullptr, TRUE, FALSE, nullptr);
        TEST_CHECK(ctx.exit_ev != nullptr, "reset: exit event created");
        hv2::WorkerManager mgr(&detail::FakeHandshakeSpawn, [](HANDLE, void*) {}, &ctx);
        mgr.SetTranslateExePath(self);
        mgr.RegisterFamily(kTranslateFamily, self);
        mgr.RegisterTranslatePoolBootEntry();
        mgr.SetVramBytesResolver([](const std::string&) { return 700ull * kMiB; });
        mgr.SetFreeVramProbe([](unsigned long long& out) { out = 8ull * 1024 * kMiB; return true; });

        TEST_CHECK(!mgr.ResetTranslatePoolAccounting("no-such-id"),
                   "reset: an unknown model_id answers false");
        hv2::TranslatePoolEntry* e = mgr.TranslatePoolEnsure("zz-rem");
        TEST_CHECK(e != nullptr, "reset: the entry exists");
        hv2::WorkerHandle* w = mgr.EnsureSpawned(e->family);
        if (ctx.hs_thread.joinable()) ctx.hs_thread.join();
        TEST_CHECK(w != nullptr && w->state == hv2::WorkerState::Ready,
                   "reset: spawn reached Ready (the entry is charged)");
        TEST_CHECK(mgr.TranslatePoolReservedVramBytes() == 700ull * kMiB,
                   "reset: the tracker holds the entry's contribution");
        mgr.TranslatePoolMarkRelayed("zz-rem", reinterpret_cast<HANDLE>(1));
        TEST_CHECK(mgr.ResetTranslatePoolAccounting("zz-rem"),
                   "reset: an existing entry is reset");
        TEST_CHECK(mgr.TranslatePoolSize() == 2,
                   "reset: the entry SURVIVES (boot + zz-rem; nothing erased)");
        TEST_CHECK(e != nullptr && e->reserved_vram_bytes == 0 &&
                       mgr.TranslatePoolReservedVramBytes() == 0,
                   "reset: the exact reserved-VRAM contribution is restored");
        TEST_CHECK(e->relayed_model_id.empty() && e->relayed_worker_process == nullptr,
                   "reset: the relay snapshot is cleared (re-relay on the next job)");
        // The pre-reset pointer stays usable — the exact class the runtime
        // erase violated (the cleared snapshot makes the next job re-relay).
        TEST_CHECK(mgr.TranslatePoolNeedsRelay("zz-rem", reinterpret_cast<HANDLE>(1)),
                   "reset: the cleared snapshot makes the next job re-relay");
        TEST_CHECK(mgr.ResetTranslatePoolAccounting("zz-rem"),
                   "reset: a second reset is a harmless true no-op (the entry persists)");
        ::CloseHandle(ctx.exit_ev);
    }

    // ---- 6. Bundled-id normalization (deepseek F-07): an explicit bundled
    //         id and the legacy "" pin share ONE pool entry/family ----------
    {
        hv2::WorkerManager mgr([](const hv2::SpawnRequest&, void*) { return hv2::SpawnResult{}; },
                               [](HANDLE, void*) {}, nullptr);
        mgr.SetTranslateExePath(self);
        mgr.RegisterFamily(kTranslateFamily, self);
        mgr.RegisterTranslatePoolBootEntry();
        mgr.SetBundledModelIdResolver([] { return std::string("hy-mt2-1.8b-q8"); });
        hv2::TranslatePoolEntry* legacy = mgr.TranslatePoolEnsure("");
        hv2::TranslatePoolEntry* bundled = mgr.TranslatePoolEnsure("hy-mt2-1.8b-q8");
        TEST_CHECK(legacy != nullptr && bundled == legacy,
                   "bundled: the explicit bundled id normalizes onto the \"\" entry");
        TEST_CHECK(bundled != nullptr && bundled->family == std::wstring(kTranslateFamily),
                   "bundled: the normalized entry serves the bare ggml-translate family");
        TEST_CHECK(mgr.TranslatePoolSize() == 1,
                   "bundled: one entry total (no second family for the same model)");
        // REQ-060 (re-review P2): the relay snapshot resolves the SAME
        // normalized "" entry — the default path (raw bundled id every job)
        // must settle after the first relay instead of find()-missing per job.
        TEST_CHECK(mgr.TranslatePoolNeedsRelay("hy-mt2-1.8b-q8", reinterpret_cast<HANDLE>(1)),
                   "bundled relay: the untouched snapshot still needs the first relay");
        mgr.TranslatePoolMarkRelayed("hy-mt2-1.8b-q8", reinterpret_cast<HANDLE>(1));
        TEST_CHECK(legacy != nullptr && legacy->relayed_model_id == "hy-mt2-1.8b-q8" &&
                       legacy->relayed_worker_process == reinterpret_cast<HANDLE>(1),
                   "bundled relay: MarkRelayed lands on the shared \"\" entry, storing the RAW id");
        TEST_CHECK(!mgr.TranslatePoolNeedsRelay("hy-mt2-1.8b-q8", reinterpret_cast<HANDLE>(1)),
                   "bundled relay: the settled snapshot matches on the raw bundled id (no per-job relay)");
        TEST_CHECK(mgr.TranslatePoolNeedsRelay("hy-mt2-1.8b-q8", reinterpret_cast<HANDLE>(2)),
                   "bundled relay: a changed worker process still forces the re-relay (REQ-058)");
        // The id comparison stays RAW by design: a "" pin after a bundled-id
        // relay still reads as a change (redundant but idempotent re-relay).
        mgr.TranslatePoolMarkRelayed("", reinterpret_cast<HANDLE>(1));
        TEST_CHECK(mgr.TranslatePoolNeedsRelay("hy-mt2-1.8b-q8", reinterpret_cast<HANDLE>(1)),
                   "bundled relay: raw '' vs the recorded bundled id still compares as a change");
        // A resolver that names no bundled entry -> no normalization.
        hv2::WorkerManager mgr2([](const hv2::SpawnRequest&, void*) { return hv2::SpawnResult{}; },
                                [](HANDLE, void*) {}, nullptr);
        mgr2.SetTranslateExePath(self);
        mgr2.RegisterFamily(kTranslateFamily, self);
        mgr2.RegisterTranslatePoolBootEntry();
        mgr2.SetBundledModelIdResolver([] { return std::string(); });
        hv2::TranslatePoolEntry* empty_res = mgr2.TranslatePoolEnsure("hy-mt2-1.8b-q8");
        TEST_CHECK(empty_res != nullptr &&
                       empty_res->family == std::wstring(L"ggml-translate-hy-mt2-1.8b-q8"),
                   "bundled: an empty resolver answer keeps the id's own family");
        // No resolver at all -> the pre-fix legacy shape is unchanged.
        hv2::WorkerManager mgr3([](const hv2::SpawnRequest&, void*) { return hv2::SpawnResult{}; },
                                [](HANDLE, void*) {}, nullptr);
        mgr3.SetTranslateExePath(self);
        mgr3.RegisterFamily(kTranslateFamily, self);
        mgr3.RegisterTranslatePoolBootEntry();
        hv2::TranslatePoolEntry* plain = mgr3.TranslatePoolEnsure("hy-mt2-1.8b-q8");
        TEST_CHECK(plain != nullptr &&
                       plain->family == std::wstring(L"ggml-translate-hy-mt2-1.8b-q8"),
                   "bundled: without the resolver the id keeps its own family (legacy shape)");
    }

    // ---- 7. Claim-phase warmup re-check (code-reviewer F1): a hold landing
    //         between the candidate collection and the claim keeps the family
    //         Ready ----------------------------------------------------------------
    {
        struct TwoFamilyCtx {
            detail::FakeHandshakeCtx a; // the bare "" family
            detail::FakeHandshakeCtx b; // the "zz-b" family
        };
        static TwoFamilyCtx tf_ctx;
        tf_ctx = TwoFamilyCtx{};
        tf_ctx.a.exit_ev = ::CreateEventW(nullptr, TRUE, FALSE, nullptr);
        tf_ctx.b.exit_ev = ::CreateEventW(nullptr, TRUE, FALSE, nullptr);
        TEST_CHECK(tf_ctx.a.exit_ev != nullptr && tf_ctx.b.exit_ev != nullptr,
                   "claim-hold: exit events created");
        hv2::WorkerManager mgr(
            [](const hv2::SpawnRequest& req, void* user) -> hv2::SpawnResult {
                auto* c = static_cast<TwoFamilyCtx*>(user);
                // The spawn carries its family; route to the matching
                // handshake ctx (EnsureSpawned serializes spawns under mu, so
                // one user ctx serves both families).
                if (req.family == std::wstring(L"ggml-translate-zz-b")) {
                    return detail::FakeHandshakeSpawn(req, &c->b);
                }
                return detail::FakeHandshakeSpawn(req, &c->a);
            },
            [](HANDLE, void*) {}, &tf_ctx);
        mgr.SetTranslateExePath(self);
        mgr.RegisterFamily(kTranslateFamily, self);
        mgr.RegisterTranslatePoolBootEntry();
        mgr.SetVramBytesResolver([](const std::string&) { return 700ull * kMiB; });
        mgr.SetFreeVramProbe([](unsigned long long& out) { out = 8ull * 1024 * kMiB; return true; });
        mgr.SetWorkerIdleMs(5000);

        hv2::WorkerHandle* wa = mgr.EnsureSpawned(kTranslateFamily);
        if (tf_ctx.a.hs_thread.joinable()) tf_ctx.a.hs_thread.join();
        hv2::TranslatePoolEntry* eb = mgr.TranslatePoolEnsure("zz-b");
        hv2::WorkerHandle* wb = mgr.EnsureSpawned(eb->family);
        if (tf_ctx.b.hs_thread.joinable()) tf_ctx.b.hs_thread.join();
        TEST_CHECK(wa != nullptr && wa->state == hv2::WorkerState::Ready &&
                       wb != nullptr && wb->state == hv2::WorkerState::Ready,
                   "claim-hold: both families reached Ready");
        TEST_CHECK(mgr.TranslatePoolReservedVramBytes() == 1400ull * kMiB,
                   "claim-hold: both families charged");

        // Both families are idle-past-budget with no hold -> both are
        // collected. A is claimed first and its stop blocks ~2 s in the
        // kill-escalation window (the fake process event never signals); the
        // helper registers B's warmup hold inside that window — AFTER B was
        // collected but BEFORE B's claim. The claim-phase re-check must then
        // spare B.
        const int64_t t0 = test_now_ms();
        std::thread helper([&mgr] {
            ::Sleep(300); // lands well inside A's ~2 s stop window
            mgr.RegisterWarmupConnection(L"ggml-translate-zz-b");
        });
        TEST_CHECK(mgr.ReaperPass(t0 + 60000) == 0,
                   "claim-hold: the pass evicts without a crash");
        helper.join();
        TEST_CHECK(mgr.State(kTranslateFamily) == hv2::WorkerState::Stopped,
                   "claim-hold: A (unheld) is evicted");
        TEST_CHECK(mgr.State(eb->family) == hv2::WorkerState::Ready,
                   "claim-hold: B survives — the hold landed before its claim");
        TEST_CHECK(mgr.WarmupConnectionCount(eb->family) == 1,
                   "claim-hold: B's hold is tracked");
        TEST_CHECK(mgr.TranslatePoolReservedVramBytes() == 700ull * kMiB,
                   "claim-hold: A's contribution was restored; B's stays charged");
        mgr.UnregisterWarmupConnection(eb->family);
        ::CloseHandle(tf_ctx.a.exit_ev);
        ::CloseHandle(tf_ctx.b.exit_ev);
    }

    if (g_failed_count == failures_before) {
        std::cout << "[PASS] REQ-060 worker idle eviction + warmup hold tests completed."
                  << std::endl;
    } else {
        std::cout << "[FAIL] REQ-060 worker idle eviction + warmup hold tests: "
                  << (g_failed_count - failures_before) << " check(s) failed." << std::endl;
    }
}

// REQ-046 P4-2 (Rev2 §B-3 + §C-3, Ask Light Gate C3): structural pins for the
// tray 4-way menu + the main.cpp on_select_engine reconstruction. main.cpp /
// tray.cpp are GUI TUs not linked into run_tests.exe, so the properties are
// pinned by source inspection (the TestReq045EngineUnavailableModal
// precedent: read the TU text from the test CWD and assert the required
// shapes exist / the removed shapes do not).
void TestReq046TrayMenuStructure() {
    std::cout << "[TEST] REQ-046 P4-2 tray 4-way menu structural pins..." << std::endl;
    const int failures_before = g_failed_count;

    auto read_src = [](const char* name, std::string& out) {
        const char* candidates[] = {name, (std::string("../") + name).c_str(),
                                    (std::string("../../") + name).c_str()};
        for (const char* cand : candidates) {
            std::ifstream in(cand, std::ios::binary);
            if (in) {
                out.assign((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
                return;
            }
        }
    };
    std::string tray_src;
    read_src("src/ui/tray.cpp", tray_src);
    std::string main_src;
    read_src("src/main.cpp", main_src);
    if (tray_src.empty() || main_src.empty()) {
        std::cout << "[SKIP] tray.cpp/main.cpp not resolvable from the test CWD; REQ-046 P4-2 pins skipped."
                  << std::endl;
        return;
    }

    // 1. The checkable 사용자 선택(.gguf) entry exists with the pref==3 rule.
    TEST_CHECK(tray_src.find("pref == 3 ? MF_CHECKED : MF_UNCHECKED") != std::string::npos &&
               tray_src.find("ID_TRAY_ENGINE_USER_GGUF") != std::string::npos,
               "tray: 사용자 선택(.gguf) is a checkable engine item (pref==3, ID_TRAY_ENGINE_USER_GGUF)");

    // 2. REQ-050: the standalone file-picker row is merged into the single
    //    manager row (ID_TRAY_MANAGE_GGUF, plain MF_STRING); the browse row
    //    append is gone (its ID constant stays defined for the frozen band).
    TEST_CHECK(tray_src.find("MF_STRING, ID_TRAY_BROWSE_GGUF") == std::string::npos,
               "tray (REQ-050): the standalone 파일찾기(.gguf) row is removed");
    TEST_CHECK(tray_src.find("MF_STRING, ID_TRAY_MANAGE_GGUF") != std::string::npos,
               "tray (REQ-050): the single merged manager row is a plain MF_STRING item");

    // 2b. REQ-050 user items 3-1/3-2: the checkable 사용자 선택(.gguf) entry
    //     is appended ONLY while a user model is registered (no model -> the
    //     manager row is the sole user-model entry), and the " — <stem>"
    //     suffix shows regardless of the checked engine (the old pref==3
    //     gate and the "(미등록)" placeholder are gone). The frozen radio ID
    //     and the 4-way check mark survive inside the conditional.
    TEST_CHECK(tray_src.find("if (!user_model_stem.empty())") != std::string::npos &&
               tray_src.find("if (pref == 3)") == std::string::npos,
               "tray (REQ-050 3-1/3-2): user-gguf entry conditional on registration, "
               "stem suffix not gated on pref==3");
    TEST_CHECK(tray_src.find("ID_TRAY_ENGINE_USER_GGUF, user_gguf_label.c_str())") !=
                   std::string::npos,
               "tray (REQ-050 3-1/3-2): the conditional entry keeps the frozen "
               "ID_TRAY_ENGINE_USER_GGUF radio ID");
    TEST_CHECK(tray_src.find("StringId::MenuEngineUserGgufEmpty") == std::string::npos,
               "tray (REQ-050 3-1): the '(미등록)' placeholder left the menu with the "
               "always-append entry");

    // 3. The nested POPUP is gone (0 hits required).
    TEST_CHECK(tray_src.find("hUserGgufMenu") == std::string::npos,
               "tray: nested hUserGgufMenu POPUP removed");

    // 4. REQ-056: the engine-menu resolver derives the check index via the
    //    shared 4-way helper (the mapping itself — every arm — is
    //    behaviorally pinned by TestReq054ToggleStemPreserve's
    //    TrayPreferredEngineIndex block).
    TEST_CHECK(main_src.find("SetEngineMenuResolver") != std::string::npos &&
                   main_src.find("TrayPreferredEngineIndex(snap.engine_type)") !=
                       std::string::npos,
               "main: the engine-menu resolver derives preferred_engine via the shared "
               "TrayPreferredEngineIndex helper (user_gguf -> 3)");

    // 4b. REQ-050 user items 3-1/3-2: refresh_tray resolves the user-model
    //     stem whenever a model is REGISTERED (no engine_type gate), so the
    //     tray can show the checkable entry + stem under any checked engine.
    TEST_CHECK(main_src.find("if (!config.user_model_id.empty())") != std::string::npos &&
               main_src.find("\"user_gguf\" && !config.user_model_id.empty()") ==
                   std::string::npos,
               "main (REQ-050 3-1/3-2): stem resolution is engine-agnostic once a model "
               "is registered");

    // 4c. REQ-050 Q2 (real-device finding, one-shot entry): an EMPTY binding
    //     with a REGISTERED user model must not orphan the checkable entry —
    //     refresh_tray falls back to the FIRST origin=="user" registry entry
    //     for the stem, and clicking the entry BINDS that entry
    //     (SetUserModelId(fallback_id) + the user_gguf switch, mirroring the
    //     RegisterUserGgufModel reuse branch). The INV-B3 manager open runs
    //     only when NO user model is registered at all.
    TEST_CHECK(main_src.find("m.origin == \"user\" && !m.files.empty()") != std::string::npos,
               "main (REQ-050 Q2): the origin==\"user\" fallback scan exists (refresh_tray "
               "+ engine-select coordinator)");
    TEST_CHECK(main_src.find("config.SetUserModelId(fallback_id)") != std::string::npos,
               "main (REQ-050 Q2): the empty-binding select binds the first registered "
               "user model instead of opening the manager");
    TEST_CHECK(main_src.find("IsSameUserGgufStem(m.files[0], stem)") != std::string::npos,
               "main (REQ-050 Q2): re-adding a source after a suffix-bump reuses the "
               "registered entry (normalized stem match, no duplicate copy)");

    // 5. on_select_engine is the explicit 4-way chain: engine_idx==3 branch,
    //    OpenAI demoted from else-terminator to else if (engine_idx == 2).
    TEST_CHECK(main_src.find("} else if (engine_idx == 2) {") != std::string::npos &&
               main_src.find("} else if (engine_idx == 3) {") != std::string::npos,
               "main: on_select_engine explicit 4-way (else if (engine_idx == 2/3))");

    if (g_failed_count == failures_before) {
        std::cout << "[PASS] REQ-046 P4-2 tray 4-way menu structural pins passed." << std::endl;
    } else {
        std::cout << "[FAIL] REQ-046 P4-2 tray 4-way menu structural pins: "
                  << (g_failed_count - failures_before) << " check(s) failed." << std::endl;
    }
}

// REQ-046 P4-3 (Tech Gate 필수-5): template style bit pins. The dialog template
// builder is now a public emebalachat symbol (declaration in
// openai_settings_window.hpp), so the unit suite instantiates it directly and
// reads DLGTEMPLATE.style — no DialogBoxIndirectParamW, no modal loop, fully
// headless. This pins the three flags the Rev2 §C design mandates:
//   WS_VISIBLE        — the dialog actually SHOWS (absence produced the
//                       "최소화된 창, 입력 불가" symptom)
//   DS_CENTER         — centered on the owner screen
//   DS_SETFOREGROUND  — brought to the foreground (Tech Gate 권고-6)
void TestReq046OpenAiTemplateStyle() {
    std::cout << "[TEST] REQ-046 P4-3 OpenAI dialog template style bits..." << std::endl;
    const int failures_before = g_failed_count;

    TemplateBuilder tb;
    tb.Begin(L"probe", 210, 130, /*itemCount=*/0);
    const DLGTEMPLATE* dt = tb.Get();
    TEST_CHECK(dt != nullptr, "template builder returns a non-null DLGTEMPLATE");
    if (dt) {
        TEST_CHECK((dt->style & WS_VISIBLE) != 0,
                   "template style includes WS_VISIBLE (dialog shows)");
        TEST_CHECK((dt->style & DS_CENTER) != 0,
                   "template style includes DS_CENTER (centered)");
        TEST_CHECK((dt->style & DS_SETFOREGROUND) != 0,
                   "template style includes DS_SETFOREGROUND (foreground guarantee)");
        // Baseline style bits that must survive the edit (regression guard).
        TEST_CHECK((dt->style & WS_POPUP) != 0 && (dt->style & WS_CAPTION) != 0 &&
                   (dt->style & WS_SYSMENU) != 0 && (dt->style & DS_SETFONT) != 0 &&
                   (dt->style & DS_MODALFRAME) != 0,
                   "template style keeps the pre-existing WS_POPUP|WS_CAPTION|WS_SYSMENU|DS_SETFONT|DS_MODALFRAME bits");
        TEST_CHECK(dt->cdit == 0, "cdit field round-trips the Begin() itemCount");
    }

    if (g_failed_count == failures_before) {
        std::cout << "[PASS] REQ-046 P4-3 OpenAI template style bits passed." << std::endl;
    } else {
        std::cout << "[FAIL] REQ-046 P4-3 OpenAI template style bits: "
                  << (g_failed_count - failures_before) << " check(s) failed." << std::endl;
    }
}

// REQ-046 P4-3 (Tech Gate 필수-4): the http://127.0.0.1:<port>/v1 base URL that
// a local mock server serves classifies as OpenAiUrlSecurity::Http, and the
// two client entry points (ListModels / ChatCompletion) enforce the documented
// gate: Http + http_consent_given=false -> reject (empty result); Http +
// http_consent_given=true -> allowed through to the transport layer. The
// unit level proves the CLASSIFICATION + GATE LOGIC; the live round-trip
// against a real mock server is gated on EMEBALA_REQ046_MOCK_PORT (see the
// report for the dynamic run output).
void TestReq046OpenAiLocalhostConsent() {
    std::cout << "[TEST] REQ-046 P4-3 OpenAI localhost http consent gate..." << std::endl;
    const int failures_before = g_failed_count;

    // Classification pins: loopback forms must all classify Http (never
    // Invalid/Https) so the consent path is reachable for local mocks.
    TEST_CHECK(ClassifyOpenAiBaseUrl("http://127.0.0.1:8080/v1") == OpenAiUrlSecurity::Http,
               "http://127.0.0.1:8080/v1 classified Http (mock-server shape)");
    TEST_CHECK(ClassifyOpenAiBaseUrl("http://127.0.0.1:8080") == OpenAiUrlSecurity::Http,
               "http://127.0.0.1:8080 (no path) classified Http");
    TEST_CHECK(ClassifyOpenAiBaseUrl("http://localhost:11434/v1") == OpenAiUrlSecurity::Http,
               "http://localhost:11434/v1 classified Http");
    TEST_CHECK(ClassifyOpenAiBaseUrl("https://127.0.0.1:8443/v1") == OpenAiUrlSecurity::Https,
               "https loopback classified Https (not Http)");

    // Gate-logic pins (mirrors openai_compatible_client.cpp L584 / L617):
    // (sec == Http && !consent) -> rejected. Prove the rejection happens
    // BEFORE any network I/O by pointing at a guaranteed-closed port: if the
    // gate leaked, the call would attempt a connection and (worst case) hang
    // on a blackhole — the closed-port form returns immediately either way,
    // and the empty result with consent=false proves the gate fired.
    {
        OpenAiConfig cfg;
        cfg.base_url = "http://127.0.0.1:1/v1";  // port 1: nothing listens
        cfg.model = "mock-model";
        cfg.http_consent_given = false;
        const std::vector<std::string> models =
            OpenAiCompatibleClient::ListModels(cfg);
        TEST_CHECK(models.empty(),
                   "ListModels rejects http:// without consent (gate fires pre-transport)");
    }
    {
        OpenAiConfig cfg;
        cfg.base_url = "http://127.0.0.1:1/v1";
        cfg.model = "mock-model";
        cfg.http_consent_given = false;
        const std::wstring out =
            OpenAiCompatibleClient::ChatCompletion(cfg, "en", "ko", L"hello");
        TEST_CHECK(out.empty(),
                   "ChatCompletion rejects http:// without consent (gate fires pre-transport)");
    }

    // Dynamic mock round-trip (필수-4 live proof): only when the env var is
    // set by the harness that started tools_tmp_req046_openai_mock.py. The
    // mock serves /v1/models + /v1/chat/completions on 127.0.0.1:<port>.
    // (_dupenv_s: the secure getenv — keeps the suite C4996-clean under /W4.)
    char* port_env_buf = nullptr;
    size_t port_env_len = 0;
    const bool have_mock_port =
        _dupenv_s(&port_env_buf, &port_env_len, "EMEBALA_REQ046_MOCK_PORT") == 0 &&
        port_env_buf != nullptr;
    if (have_mock_port) {
        // Copy the port out BEFORE freeing the env buffer — REQ-050's second
        // leg (bare-host base) needs it too (reading it after free() was a
        // use-after-free that produced a garbage base URL).
        const std::string mock_port = port_env_buf;
        free(port_env_buf);
        const std::string base = "http://127.0.0.1:" + mock_port + "/v1";
        OpenAiConfig cfg;
        cfg.base_url = base;
        cfg.model = "mock-model";
        // The client requires a DPAPI-protected key (WithUnprotectedKey fails
        // closed on an empty api_key_dpapi — openai_compatible_client.cpp
        // L467), so protect a dummy key and pin its integrity digest the same
        // way the settings dialog does on save.
        std::string dummy_key = "sk-req046-mock-dummy-key";
        TEST_CHECK(ProtectOpenAiApiKey(dummy_key, cfg.api_key_dpapi) &&
                   !cfg.api_key_dpapi.empty(),
                   "mock setup: DPAPI-protect the dummy key");
        TEST_CHECK(OpenAiSha256Hex(std::string("sk-req046-mock-dummy-key"),
                                   cfg.api_key_sha256),
                   "mock setup: integrity digest for the dummy key");
        cfg.http_consent_given = true;  // Tech Gate 필수-4: consent REQUIRED for http

        const std::vector<std::string> models =
            OpenAiCompatibleClient::ListModels(cfg);
        TEST_CHECK(!models.empty() &&
                   std::find(models.begin(), models.end(), "mock-model") != models.end(),
                   "mock /v1/models round-trip returns the mock model id");

        const std::wstring out =
            OpenAiCompatibleClient::ChatCompletion(cfg, "en", "ko", L"hello");
        // REQ-050: the req050 mock (tools_tmp_req050/openai_mock_server.py)
        // returns "MOCK-TRANSLATED"; the stale req046 tmp mock returned
        // "mock-translation". The req050 mock is the canonical one now.
        TEST_CHECK(out == L"MOCK-TRANSLATED",
                   "mock /v1/chat/completions round-trip returns the mock translation");

        // REQ-050: the second confirmed root cause was the DOUBLE /v1 path
        // (base ".../v1" + "/v1/models" -> ".../v1/v1/models" -> 404). The
        // live proof therefore exercises BOTH canonical base forms: with and
        // without the /v1 prefix. (The mock matches on path SUFFIX, so the
        // old buggy join could still pass that leg — the req050 mock probe
        // under tools_tmp_req050/ pins the exact paths; here we prove the
        // base-URL forms end-to-end.) The /v1 leg above already covers the
        // prefixed form; this leg covers the bare-host form.
        const std::string base_no_v1 = "http://127.0.0.1:" + mock_port;
        OpenAiConfig cfg2;
        cfg2.base_url = base_no_v1;  // no /v1 prefix: client must assume /v1
        cfg2.model = "mock-model";
        cfg2.api_key_dpapi = cfg.api_key_dpapi;
        cfg2.api_key_sha256 = cfg.api_key_sha256;
        cfg2.http_consent_given = true;
        const std::vector<std::string> models2 =
            OpenAiCompatibleClient::ListModels(cfg2);
        TEST_CHECK(!models2.empty() &&
                   std::find(models2.begin(), models2.end(), "mock-model") != models2.end(),
                   "REQ-050: mock round-trip with base http://host:port (no /v1) succeeds");
        const std::wstring out2 =
            OpenAiCompatibleClient::ChatCompletion(cfg2, "en", "ko", L"hello");
        TEST_CHECK(out2 == L"MOCK-TRANSLATED",
                   "REQ-050: chat round-trip with base http://host:port (no /v1) succeeds");
    } else {
        std::cout << "[SKIP] EMEBALA_REQ046_MOCK_PORT not set; live mock round-trip skipped "
                     "(run tools_tmp_req046_openai_mock.py + set the env var for the dynamic proof)."
                  << std::endl;
    }

    if (g_failed_count == failures_before) {
        std::cout << "[PASS] REQ-046 P4-3 OpenAI localhost http consent gate passed." << std::endl;
    } else {
        std::cout << "[FAIL] REQ-046 P4-3 OpenAI localhost http consent gate: "
                  << (g_failed_count - failures_before) << " check(s) failed." << std::endl;
    }
}

// REQ-046 P4-3 (Rev2 C-1): structural pin — the OpenAI settings dialog must be
// parented to g_hControllerWnd, never nullptr. nullptr parent is what produced
// the ownerless "minimized window" symptom (no activation/foreground transfer).
void TestReq046OpenAiDialogParent() {
    std::cout << "[TEST] REQ-046 P4-3 OpenAI dialog parent handle pin..." << std::endl;
    const int failures_before = g_failed_count;

    auto read_src = [](const char* name, std::string& out) {
        const char* candidates[] = {name, (std::string("../") + name).c_str(),
                                    (std::string("../../") + name).c_str()};
        for (const char* cand : candidates) {
            std::ifstream in(cand, std::ios::binary);
            if (in) {
                out.assign((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
                return;
            }
        }
    };
    std::string main_src;
    read_src("src/main.cpp", main_src);
    if (main_src.empty()) {
        std::cout << "[SKIP] src/main.cpp not resolvable from the test CWD; REQ-046 P4-3 parent pin skipped."
                  << std::endl;
        return;
    }

    // 1. The nullptr-parent call shape is gone (0 hits required).
    TEST_CHECK(main_src.find("ShowOpenAiSettingsDialog(/*parent=*/nullptr") == std::string::npos,
               "main: ShowOpenAiSettingsDialog(nullptr) removed");
    // 2. The g_hControllerWnd-parent call shape exists.
    TEST_CHECK(main_src.find("ShowOpenAiSettingsDialog(\n                    /*parent=*/emebalachat::g_hControllerWnd, edited)") != std::string::npos ||
               main_src.find("/*parent=*/emebalachat::g_hControllerWnd, edited") != std::string::npos,
               "main: ShowOpenAiSettingsDialog parented to g_hControllerWnd");

    if (g_failed_count == failures_before) {
        std::cout << "[PASS] REQ-046 P4-3 OpenAI dialog parent pin passed." << std::endl;
    } else {
        std::cout << "[FAIL] REQ-046 P4-3 OpenAI dialog parent pin: "
                  << (g_failed_count - failures_before) << " check(s) failed." << std::endl;
    }
}

// ===========================================================================
// R1-1 + R1-2 (session 261029_0001, v0.10.4 sweep): the output-quality gate
// and the greedy-branch sampler shape. Headless: every predicate is pure text
// / pure decision logic (declared in src/engine_core/translation_common.hpp,
// defined in translation_common.cpp OUTSIDE the HAVE_LLAMA_CPP block), so no
// GGUF is loaded. The positive legs reuse the EXACT strings the debug reports
// captured live (docs/261029_0001_session_v0.10.4-sweep/
// debug-specialist-report-k3agent.md RC1/RC2/RC4 and
// debug-specialist-report-step5.md §4 F1/F2); the negative legs are the
// controls that must keep translating (CEO intent: garbage is rejected, real
// translations are never touched).
// Registered in main() right after TestS260930ChunkStitch().
// ===========================================================================
void TestS261029UaOutputGate() {
    std::cout << "[RUN] Testing R1-1 output gate + R1-2 sampler shape (261029_0001)..." << std::endl;
    const int failures_before = g_failed_count;

    // ---- R1-2: sampler-shape decision table ----
    // The shipped profile (worker_protocol.hpp defaults / host stamp) is
    // temperature 0.0 + rep_pen 1.05: that combination MUST take the penalized
    // chain, because the pre-R1-2 code silently dropped the penalty there.
    static_assert(kGreedyTemperatureThreshold == 0.001f,
                  "R1-2: the greedy branch boundary stays at the pre-R1-2 0.001f");
    TEST_CHECK(DecideSamplerShape(0.0f, 1.05f) == SamplerShape::PenalizedGreedy,
               "R1-2: shipped profile (temp 0.0, rep_pen 1.05) -> penalties -> greedy chain");
    TEST_CHECK(DecideSamplerShape(0.001f, 1.05f) == SamplerShape::PenalizedGreedy,
               "R1-2: greedy boundary is INCLUSIVE (temp 0.001 still greedy)");
    TEST_CHECK(DecideSamplerShape(0.0011f, 1.05f) == SamplerShape::Dist,
               "R1-2: above the boundary the unchanged dist chain runs");
    TEST_CHECK(DecideSamplerShape(0.7f, 1.05f) == SamplerShape::Dist,
               "R1-2: sampled decoding keeps the existing penalty/top_k/top_p/temp/dist chain");
    TEST_CHECK(DecideSamplerShape(0.0f, 1.0f) == SamplerShape::BareGreedy,
               "R1-2: rep_pen == 1.0 (penalty disabled) keeps the bare greedy sampler BYTE-IDENTICAL");
    TEST_CHECK(DecideSamplerShape(0.0f, 0.0f) == SamplerShape::BareGreedy,
               "R1-2: rep_pen <= 1.0 never builds a chain");
    TEST_CHECK(DecideSamplerShape(0.0f, 0.9f) == SamplerShape::BareGreedy,
               "R1-2: a sub-1.0 penalty value cannot change the shape either");
    TEST_CHECK(DecideSamplerShape(-1.0f, 1.05f) == SamplerShape::PenalizedGreedy,
               "R1-2: negative temperature keeps the historical greedy branch (no new clamp)");
    TEST_CHECK(DecideSamplerShape(0.7f, 1.0f) == SamplerShape::Dist,
               "R1-2: the sampled branch is selected by TEMPERATURE alone");

    // ---- R1-1 repetition, rule A: identical line repeated >= 3 times ----
    // Live repro (k3agent RC2 / step5 C4): "np" -> "npi\nnpi\n..." x64.
    std::wstring line_loop;
    for (int i = 0; i < 64; ++i) {
        line_loop += L"npi\n";
    }
    TEST_CHECK(HasRepeatedLineOrTokenRun(line_loop),
               "R1-1: 64 identical 'npi' lines are a repetition loop (live repro)");
    TEST_CHECK(HasRepeatedLineOrTokenRun(L"npi\nnpi\nnpi"),
               "R1-1: exactly 3 identical lines already trip the rule");
    TEST_CHECK(!HasRepeatedLineOrTokenRun(L"npi\nnpi"),
               "R1-1: 2 identical lines are below the threshold");
    TEST_CHECK(!HasRepeatedLineOrTokenRun(L"first line\nsecond line\nthird line"),
               "R1-1: three DISTINCT lines are not a loop");
    TEST_CHECK(HasRepeatedLineOrTokenRun(L"  npi  \nnpi\n\tnpi\t"),
               "R1-1: line comparison trims surrounding whitespace (CRLF/tab tolerant)");
    TEST_CHECK(HasRepeatedLineOrTokenRun(L"first\n\n\nsecond\nsecond\nsecond"),
               "R1-1: blank lines are ignored, not counted as repeats");

    // ---- R1-1 repetition, rule B: one token repeated >= 3 times in a row ----
    TEST_CHECK(HasRepeatedLineOrTokenRun(L"assistant assistant assistant"),
               "R1-1: a token repeated 3x in a row is a degenerate run");
    TEST_CHECK(!HasRepeatedLineOrTokenRun(L"assistant assistant"),
               "R1-1: a 2x token run is below the threshold");
    TEST_CHECK(!HasRepeatedLineOrTokenRun(L"the cat sat on the mat"),
               "R1-1: ordinary prose is never a token-run loop");

    // ---- R2-6 (code-reviewer-mimo F-01): the calibrated Rule A/B envelope ----
    // Rule A now counts CONSECUTIVE lines only: a transcript/dialogue that says
    // the same short line three times, spread out, is content.
    TEST_CHECK(!HasRepeatedLineOrTokenRun(L"Yes.\nNo.\nYes.\nMaybe.\nYes."),
               "R2-6: identical lines spread through a dialogue are not a loop (consecutive-only)");
    TEST_CHECK(HasRepeatedLineOrTokenRun(L"Yes.\nNo.\nYes.\nYes.\nYes."),
               "R2-6: a CONSECUTIVE identical-line run still trips rule A");
    // Rule B must-pass reduplication, BOTH directions. These are the cases the
    // pre-R2-6 header claimed were exempt and the gate rejected end-to-end.
    TEST_CHECK(!OutputHasRepetition(L"no no no", L"no no no"),
               "R2-6: 'no no no' accepted when the source carries the same reduplication");
    TEST_CHECK(!OutputHasRepetition(L"no no no", L"아니 아니 아니"),
               "R2-6: KO source reduplication -> EN 'no no no' accepted (KO->EN must-pass)");
    TEST_CHECK(!OutputHasRepetition(L"아니 아니 아니", L"no no no"),
               "R2-6: EN source reduplication -> KO output accepted (EN->KO must-pass)");
    TEST_CHECK(!OutputHasRepetition(L"도와주세요! 도와주세요! 도와주세요!", L"Help! Help! Help!"),
               "R2-6: 'Help! Help! Help!' -> KO reduplication accepted (must-pass)");
    TEST_CHECK(!OutputHasRepetition(L"Help! Help! Help!", L"도와주세요! 도와주세요! 도와주세요!"),
               "R2-6: KO reduplication -> 'Help! Help! Help!' accepted (must-pass, EN direction)");
    // Span floor: the same three-token emphasis inside a sentence covers a small
    // fraction of the answer, so it is not a loop (3 of 11 tokens = 27%).
    TEST_CHECK(!OutputHasRepetition(L"The cat sat on the mat and said no no no"),
               "R2-6: a mid-sentence 3-token emphasis is below the 50% span floor");
    TEST_CHECK(!HasRepeatedLineOrTokenRun(L"ha ha ha that is a good one"),
               "R2-6: 3 of 8 tokens (37.5%) is still below the span floor");
    TEST_CHECK(HasRepeatedLineOrTokenRun(L"npi npi npi npi and then words here"),
               "R2-6: 4 of 8 tokens reaches the 50% span floor (boundary is inclusive)");
    // A real one-token loop still fires: 100% coverage, and the source carries
    // no reduplication to explain it.
    std::wstring token_loop;
    for (int i = 0; i < 64; ++i) {
        token_loop += L"npi ";
    }
    TEST_CHECK(HasRepeatedLineOrTokenRun(token_loop),
               "R2-6: a 64-token single-token run is still a loop (coverage 100%)");
    TEST_CHECK(OutputHasRepetition(token_loop, L"np"),
               "R2-6: the live 'np' -> 'npi npi ...' loop is still rejected with its source");
    // Documented envelope: a three-token WHOLE output with no source evidence is
    // indistinguishable from a loop, so the text-only predicate keeps rejecting
    // it (production passes the source at BOTH decode sites).
    TEST_CHECK(OutputHasRepetition(L"assistant assistant assistant"),
               "R2-6: the pre-existing 3-token run pin is unchanged (no source evidence)");
    TEST_CHECK(!OutputHasRepetition(L"assistant assistant assistant", L"도우미 도우미 도우미"),
               "R2-6: ... and the same answer IS accepted when the source reduplicates");

    // ---- R2-8 (security-reviewer-mimo L-2): the STITCHED whole ----
    // Each chunk output below is ONE line, so every per-chunk gate passes; after
    // stitching with the original paragraph separators the same line appears 3x
    // and Rule A reassembles across the chunk boundary - exactly what the
    // whole-output re-gate before `return stitched;` catches.
    TEST_CHECK(!HasRepeatedLineOrTokenRun(L"npi"),
               "R2-8: one chunk's single-line output is not a loop");
    TEST_CHECK(HasRepeatedLineOrTokenRun(L"npi\n\nnpi\n\nnpi"),
               "R2-8: Rule A reassembles across the stitched paragraph separators");
    TEST_CHECK(OutputHasRepetition(L"npi\n\nnpi\n\nnpi", L"np"),
               "R2-8: the stitched whole is rejected even with a source present");

    // ---- R1-1 repetition, rule C: >= 8-token repeating suffix ----
    // Live repro shape (step5 §4 F2): a sentence repeated to the token cap.
    std::wstring sentence_loop;
    for (int i = 0; i < 3; ++i) {
        sentence_loop += L"Please contact us for further assistance. ";
    }
    TEST_CHECK(HasSuffixRepetition(sentence_loop),
               "R1-1: a 6-token sentence repeated 3x (18-token suffix) is a loop");
    TEST_CHECK(HasSuffixRepetition(L"look out look out look out look out"),
               "R1-1: a 2-token period repeated 4x reaches the 8-token span floor");
    TEST_CHECK(!HasSuffixRepetition(L"look out look out look out"),
               "R1-1: a 2-token period repeated 3x spans only 6 tokens -> below the floor");
    TEST_CHECK(!HasSuffixRepetition(L"no no no"),
               "R1-1: a 3-token emphasis is NOT a suffix loop (span floor)");
    TEST_CHECK(HasSuffixRepetition(L"no no no no no no no no"),
               "R1-1: 8 identical tokens reach the span floor");
    TEST_CHECK(!HasSuffixRepetition(sentence_loop.substr(0, sentence_loop.size() - 29)),
               "R1-1: fewer than 3 repeats never trips the suffix rule");
    TEST_CHECK(!HasSuffixRepetition(L"The quick brown fox jumps over the lazy dog and keeps running."),
               "R1-1: a natural sentence is not a periodic suffix");

    // Documented bound: the period scan stops at kSuffixRepetitionMaxPeriodTokens
    // (a whole 64+ token sentence repeated verbatim is out of the practical
    // envelope; the line rule covers it whenever it is line-separated).
    {
        std::wstring long_phrase;
        for (int i = 0; i < 70; ++i) {
            long_phrase += L"w" + std::to_wstring(i) + L" ";
        }
        std::wstring long_loop;
        for (int i = 0; i < 3; ++i) {
            long_loop += long_phrase;
        }
        TEST_CHECK(!HasSuffixRepetition(long_loop),
                   "R1-1: period above kSuffixRepetitionMaxPeriodTokens is out of the scan bound");
        static_assert(kSuffixRepetitionMaxPeriodTokens == 64,
                      "R1-1: the documented period bound stays 64 tokens");
        static_assert(kSuffixRepetitionMinSpanTokens == 8,
                      "R1-1: the suffix span floor stays 8 tokens");
    }

    // ---- R1-1 repetition: combined predicate used by BOTH decode sites ----
    TEST_CHECK(OutputHasRepetition(line_loop),
               "R1-1: the combined predicate fires on the live line loop");
    TEST_CHECK(OutputHasRepetition(sentence_loop),
               "R1-1: the combined predicate fires on the live phrase loop");
    TEST_CHECK(!OutputHasRepetition(L"안녕하세요. 오늘 날씨가 정말 좋네요."),
               "R1-1: a normal Korean translation is not a loop");

    // ---- R1-1 script classes (reused smart_bypass predicates) ----
    TEST_CHECK(TextScriptClasses(L"hello") == ToMask(ScriptClass::Latin),
               "R1-1: Latin text classifies as Latin");
    TEST_CHECK(TextScriptClasses(L"안녕하세요") == ToMask(ScriptClass::Hangul),
               "R1-1: Hangul text classifies as Hangul");
    TEST_CHECK(TextScriptClasses(L"日本語です") ==
                   (ToMask(ScriptClass::Han) | ToMask(ScriptClass::Kana)),
               "R1-1: Japanese text carries BOTH Han and Kana");
    TEST_CHECK(TextScriptClasses(L"简体中文") == ToMask(ScriptClass::Han),
               "R1-1: Chinese text classifies as Han");
    TEST_CHECK((TextScriptClasses(L"안녕 hello") & ToMask(ScriptClass::Latin)) != 0 &&
                   (TextScriptClasses(L"안녕 hello") & ToMask(ScriptClass::Hangul)) != 0,
               "R1-1: mixed script text carries both classes");
    TEST_CHECK(TextScriptClasses(L"12345 !!!") == 0,
               "R1-1: digits/symbols carry no script class (their loops are a repetition concern)");
    TEST_CHECK(TextScriptClasses(L"") == 0, "R1-1: empty text carries no script class");
    TEST_CHECK(TextScriptClasses(L"Türkçe") == ToMask(ScriptClass::Latin),
               "R1-1: accented Latin is still Latin script");

    // Native names straight from the i18n registry: the script table must agree
    // with every registration (a new language without a script entry fails).
    TEST_CHECK(TextScriptClasses(L"Русский") == ToMask(ScriptClass::Cyrillic),
               "R1-1: Cyrillic detection");
    TEST_CHECK(TextScriptClasses(L"ไทย") == ToMask(ScriptClass::Thai),
               "R1-1: Thai detection");
    TEST_CHECK(TextScriptClasses(L"العربية") == ToMask(ScriptClass::Arabic),
               "R1-1: Arabic detection");
    TEST_CHECK(TextScriptClasses(L"עברית") == ToMask(ScriptClass::Hebrew),
               "R1-1: Hebrew detection");
    TEST_CHECK(TextScriptClasses(L"हिन्दी") == ToMask(ScriptClass::Devanagari),
               "R1-1: Devanagari detection");
    TEST_CHECK(TextScriptClasses(L"বাংলা") == ToMask(ScriptClass::Bengali),
               "R1-1: Bengali detection");
    TEST_CHECK(TextScriptClasses(L"ភាសាខ្មែរ") == ToMask(ScriptClass::Khmer),
               "R1-1: Khmer detection");
    TEST_CHECK(TextScriptClasses(L"ພາສາລາວ") == ToMask(ScriptClass::Lao),
               "R1-1: Lao detection");
    TEST_CHECK(TextScriptClasses(L"မြန်မာစာ") == ToMask(ScriptClass::Myanmar),
               "R1-1: Burmese detection");
    TEST_CHECK(TextScriptClasses(L"Ελληνικά") == ToMask(ScriptClass::Greek),
               "R1-1: Greek detection");

    // ---- R1-1 language code -> script mask ----
    TEST_CHECK(TargetScriptClasses("KO") == ToMask(ScriptClass::Hangul),
               "R1-1: KO -> Hangul");
    TEST_CHECK(TargetScriptClasses("ko") == ToMask(ScriptClass::Hangul),
               "R1-1: code lookup is case-insensitive");
    TEST_CHECK(TargetScriptClasses("JA") ==
                   (ToMask(ScriptClass::Han) | ToMask(ScriptClass::Kana)),
               "R1-1: JA -> Han|Kana (either script satisfies the target)");
    TEST_CHECK(TargetScriptClasses("ZH-CN") == ToMask(ScriptClass::Han),
               "R1-1: ZH-CN -> Han");
    TEST_CHECK(TargetScriptClasses("ZH-TW") == ToMask(ScriptClass::Han),
               "R1-1: ZH-TW -> Han");
    TEST_CHECK(TargetScriptClasses("EN") == ToMask(ScriptClass::Latin),
               "R1-1: EN -> Latin");
    TEST_CHECK(TargetScriptClasses("AUTO") == 0,
               "R1-1: AUTO resolves to no script -> the gate fails OPEN");
    TEST_CHECK(TargetScriptClasses("") == 0,
               "R1-1: empty code resolves to no script -> fail open");
    TEST_CHECK(TargetScriptClasses("XX") == 0,
               "R1-1: unknown code resolves to no script -> fail open");
    {
        int missing_script = 0;
        int native_script_mismatch = 0;
        for (const LanguageInfo& lang : GetTargetLanguages()) {
            const std::uint32_t mask = TargetScriptClasses(lang.code);
            if (mask == 0) {
                ++missing_script;
                continue;
            }
            const std::wstring native_wide = ToUtf16(lang.name_native);
            if ((TextScriptClasses(native_wide) & mask) == 0) {
                ++native_script_mismatch;
            }
        }
        TEST_CHECK(missing_script == 0,
                   "R1-1: EVERY registered target language has a script family (drift guard)");
        TEST_CHECK(native_script_mismatch == 0,
                   "R1-1: every target's native name carries its own script (table/db agreement)");
    }

    // ---- R1-1 code-point counter ----
    TEST_CHECK(CountCodePoints(L"") == 0, "R1-1: empty text has zero code points");
    TEST_CHECK(CountCodePoints(L"abc") == 3, "R1-1: ASCII length");
    TEST_CHECK(CountCodePoints(L"안녕") == 2, "R1-1: Hangul length");
    TEST_CHECK(CountCodePoints(L"\xD83D\xDE00") == 1,
               "R1-1: a surrogate pair counts as ONE code point");

    // ---- R1-1 wrong-script rule ----
    const std::uint32_t ko_mask = TargetScriptClasses("KO");
    const std::uint32_t en_mask = TargetScriptClasses("EN");
    // Live repro: EN -> KO "asdf" answered with an English essay.
    TEST_CHECK(IsWrongScriptOutput(
                   L"If you are looking for a way to make your data more accessible, here is a guide.",
                   L"asdf", ko_mask),
               "R1-1: English essay for a Korean target is wrong-script (live repro)");
    // Controls: correct answers are never rejected.
    TEST_CHECK(!IsWrongScriptOutput(L"안녕하세요.", L"asdf", ko_mask),
               "R1-1: a Korean answer for a Korean target passes");
    TEST_CHECK(!IsWrongScriptOutput(L"오늘 날씨가 어떤가요?", L"Hello, how is the weather today?", ko_mask),
               "R1-1: a normal EN->KO translation passes");
    TEST_CHECK(!IsWrongScriptOutput(L"Hello, this is a normal sentence.", L"음", en_mask),
               "R1-1: a normal KO->EN translation passes");
    TEST_CHECK(IsWrongScriptOutput(L"안녕하세요, 반갑습니다.", L"음", en_mask),
               "R1-1: a Korean answer for an English target is wrong-script "
               "(live '음' KO->EN case shape)");
    TEST_CHECK(!IsWrongScriptOutput(L"안녕하세요, 반갑습니다.", L"hello", en_mask),
               "R1-1: source already in the target script (EN->EN) never trips the gate");
    // Length floor: <= kWrongScriptMinOutputCodePoints code points never gate.
    TEST_CHECK(!IsWrongScriptOutput(L"ab", L"asdf", ko_mask),
               "R1-1: a 2-code-point answer sits below the wrong-script floor");
    TEST_CHECK(IsWrongScriptOutput(L"abc", L"asdf", ko_mask),
               "R1-1: a 3-code-point answer is gated");
    // Source-script precondition: pure digits carry no language signal.
    TEST_CHECK(!IsWrongScriptOutput(L"12345", L"12345", ko_mask),
               "R1-1: digits->digits is not a wrong-script case (no source script)");
    // Source already in the target script -> nothing to be wrong about.
    TEST_CHECK(!IsWrongScriptOutput(L"hello there", L"안녕하세요", ko_mask),
               "R1-1: source already in the target script never trips the gate");
    // Unknown target -> fail open.
    TEST_CHECK(!IsWrongScriptOutput(L"hello there", L"안녕하세요", 0),
               "R1-1: unknown/AUTO target never rejects (fail open)");

    // ---- R1-1 meta leakage ----
    // The CEO's exact "assist" repro (k3agent RC1, verbatim from the report).
    const std::wstring assist_repro =
        L"abdefghijklmnopqrstuvwxyz\nTranslation is not possible… Please contact us for "
        L"further assistance. …죄송합니다, but I can't translate this text.";
    TEST_CHECK(HasMetaLeakage(assist_repro, L"abcdefghijklmnopqrstuvwxyz"),
               "R1-1: the verbatim 'assist' repro trips the meta-leakage table");
    TEST_CHECK(HasMetaLeakage(L"Please contact us for further assistance.", L"asdf"),
               "R1-1: the refusal tail alone is leakage");
    TEST_CHECK(HasMetaLeakage(L"TRANSLATION IS NOT POSSIBLE", L"asdf"),
               "R1-1: meta matching is ASCII case-insensitive");
    TEST_CHECK(HasMetaLeakage(L"I can't translate this text.", L"asdf"),
               "R1-1: the refusal opener is leakage");
    TEST_CHECK(HasMetaLeakage(L"Sure, here is the translation:\n안녕하세요", L"asdf"),
               "R1-1: the assistant opener 'Sure, here' is leakage at line start");
    TEST_CHECK(HasMetaLeakage(L"English: hello\nKorean: 안녕하세요", L"hello world 123"),
               "R1-1: '<language>:' label lines are leakage (bilingual repro)");
    TEST_CHECK(HasMetaLeakage(L"영어: hello\n한국어: 안녕하세요", L"hello world 123"),
               "R1-1: native-script label lines are leakage");
    TEST_CHECK(HasMetaLeakage(L"中文: 你好", L"hello"),
               "R1-1: Chinese label line is leakage");
    // Controls / source guard (repo idiom: the source's own text is legitimate).
    TEST_CHECK(!HasMetaLeakage(L"안녕하세요. 오늘 날씨가 정말 좋네요.", L"hello"),
               "R1-1: a normal translation carries no meta leakage");
    TEST_CHECK(!HasMetaLeakage(L"Please contact us for further assistance.",
                               L"Please contact us for further assistance."),
               "R1-1: a phrase the SOURCE itself carries is never leakage (source guard)");
    TEST_CHECK(!HasMetaLeakage(L"English: hello", L"English: hello"),
               "R1-1: source guard covers label lines too");
    TEST_CHECK(!HasMetaLeakage(L"영어를 배우고 있습니다.", L"hello"),
               "R1-1: a native word WITHOUT the ':' label is not leakage");
    TEST_CHECK(!HasMetaLeakage(L"He said 'sure, here it is' to me.", L"hello"),
               "R1-1: the assistant opener inside a sentence does not match (line-start only)");

    // ---- R2-7 (code-reviewer-gemini F-05): a TRANSLATED colon label ----
    // The pre-R2-7 source guard required the TARGET-language needle to appear in
    // the source, which a real language pair never contains, so these legitimate
    // translations were rejected on both rungs.
    TEST_CHECK(!HasMetaLeakage(L"Source: Reuters", L"출처: 로이터"),
               "R2-7: '출처: 로이터' -> 'Source: Reuters' is a translated label, not leakage");
    TEST_CHECK(!HasMetaLeakage(L"영어: 유창함", L"English: Fluent"),
               "R2-7: 'English: Fluent' -> '영어: 유창함' is a translated label, not leakage");
    TEST_CHECK(!HasMetaLeakage(L"Name: Kim\nSource: Reuters", L"이름: 김\n출처: 로이터"),
               "R2-7: the exemption is line-indexed (each label pairs with its own source line)");
    // Still leakage: the label line has no source-side label behind it.
    TEST_CHECK(HasMetaLeakage(L"Source: Reuters", L"reuters dot com article"),
               "R2-7: 'Source:' with no colon label in the source is still leakage");
    TEST_CHECK(HasMetaLeakage(L"영어: 유창함", L"안녕하세요"),
               "R2-7: a label line the source did not carry is still leakage");
    TEST_CHECK(HasMetaLeakage(L"Sure, here is the translation:\nSource: Reuters", L"출처: 로이터"),
               "R2-7: an assistant opener plus an uncued label is still leakage");
    TEST_CHECK(HasMetaLeakage(L"hello\nSource: Reuters", L"출처: 로이터"),
               "R2-7: line index alignment is strict (output line 1 has no source line 1)");
    TEST_CHECK(!HasMetaLeakage(L"안녕하세요", L"hello world 123"),
               "R2-7: control - an output without labels is unaffected");

    // ---- F-04 (v0.10.5 review round 1): conversational openers fire only
    // for a SHORT source (<= kConversationalNeedleMaxSourceCodePoints = 15,
    // translation_common.hpp). A real sentence's translation may itself open
    // with an apology; the model only talks BACK to a word or a short phrase.
    // Colon-terminated label prefixes stay unconditional (R2-7 pins above).
    TEST_CHECK(!HasMetaLeakage(L"죄송하지만 그 요청은 도와드릴 수 없습니다.",
                               L"Sorry, but I cannot help with that"),
               "F-04: a long source's apology-opener translation is NOT leakage");
    TEST_CHECK(HasMetaLeakage(L"죄송합니다, 그건 알려드릴 수 없어요.", L"왜"),
               "F-04: a short-source talk-back opener IS leakage");
    // Boundary: a 15-code-point source still fires, a 16-code-point one does not.
    TEST_CHECK(HasMetaLeakage(L"죄송하지만 abcdefghijklmno", L"abcdefghijklmno"),
               "F-04: the 15-code-point source boundary still fires the opener");
    TEST_CHECK(!HasMetaLeakage(L"죄송하지만 abcdefghijklmnop", L"abcdefghijklmnop"),
               "F-04: a 16-code-point source no longer fires the opener");
    // End-to-end through the classifier.
    TEST_CHECK(ClassifyTranslationOutput(L"죄송하지만 그 요청은 도와드릴 수 없습니다.",
                                         L"Sorry, but I cannot help with that", "KO") ==
                   OutputRejectReason::None,
               "F-04: the long-source apology translation classifies as accepted");
    TEST_CHECK(ClassifyTranslationOutput(L"죄송합니다, 그건 알려드릴 수 없어요.", L"왜", "KO") ==
                   OutputRejectReason::MetaLeakage,
               "F-04: the short-source talk-back classifies as MetaLeakage");

    // ---- R1-1 combined gate + priority ----
    TEST_CHECK(ClassifyTranslationOutput(L"", L"asdf", "KO") == OutputRejectReason::None,
               "R1-1: empty output is the ladder's concern, not the gate's");
    TEST_CHECK(ClassifyTranslationOutput(line_loop, L"np", "KO") ==
                   OutputRejectReason::Repetition,
               "R1-1: the live line loop classifies as Repetition (repetition outranks script)");
    TEST_CHECK(ClassifyTranslationOutput(assist_repro, L"abcdefghijklmnopqrstuvwxyz", "KO") ==
                   OutputRejectReason::MetaLeakage,
               "R1-1: the verbatim 'assist' repro classifies as MetaLeakage "
               "(Hangul present -> not wrong-script)");
    TEST_CHECK(ClassifyTranslationOutput(
                   L"If you are looking for a way to make your data more accessible, here is a guide.",
                   L"asdf", "KO") == OutputRejectReason::WrongScript,
               "R1-1: the live English essay classifies as WrongScript");
    TEST_CHECK(ClassifyTranslationOutput(L"Sure, here is the translation:\n안녕하세요", L"asdf",
                                         "KO") == OutputRejectReason::MetaLeakage,
               "R1-1: assistant opener + real answer classifies as MetaLeakage");
    TEST_CHECK(ClassifyTranslationOutput(L"안녕하세요. 오늘 날씨가 정말 좋네요.", L"hello",
                                         "KO") == OutputRejectReason::None,
               "R1-1: control - a good Korean translation is accepted");
    TEST_CHECK(ClassifyTranslationOutput(L"Hello, this is a normal sentence.", L"안녕하세요. 음",
                                         "EN") == OutputRejectReason::None,
               "R1-1: control - a good English translation is accepted");
    TEST_CHECK(ClassifyTranslationOutput(L"안녕하세요", L"hello", "AUTO") ==
                   OutputRejectReason::None,
               "R1-1: AUTO target never rejects (fail open)");

    // ---- R2-16 (CEO decision "언제나 잘 번역", calibrated): the fourth rule ----
    // (i) unexpected-script share >= 30% AND > 3x length expansion. The live
    // KO->EN residual is the shape this exists for: a 1-code-point interjection
    // answered with a 977-code-point essay whose tail is Chinese.
    const std::wstring amplified_essay =
        L"The next day, I went to the hospital to see my doctor. I had a fever and was "
        L"feeling sick. I felt like I was going to vomit. I went to the emergency room and "
        L"was asked to wait in the waiting area. 第二天，我去了医院看医生。";
    TEST_CHECK(IsAmplifiedTinySourceOutput(amplified_essay, L"음"),
               "R2-16(ii): the live '음' -> essay amplification is detected");
    TEST_CHECK(ClassifyTranslationOutput(amplified_essay, L"음", "EN") ==
                   OutputRejectReason::ScriptLeak,
               "R2-16: the live '음' essay (English prose + Chinese tail) is rejected");
    TEST_CHECK(ClassifyTranslationOutput(amplified_essay, L"음", "AUTO") ==
                   OutputRejectReason::ScriptLeak,
               "R2-16(ii): the amplification rule is script-free (AUTO target included)");
    // (i) in isolation: 2-code-point source, 17-code-point mixed answer, so the
    // tiny-source floor (40) cannot be what rejects it.
    TEST_CHECK(IsUnexpectedScriptHeavyOutput(L"Hello 你好世界你好世界你好世界", L"hi", en_mask),
               "R2-16(i): mostly-unexpected script + >3x expansion is detected");
    TEST_CHECK(ClassifyTranslationOutput(L"Hello 你好世界你好世界你好世界", L"hi", "EN") ==
                   OutputRejectReason::ScriptLeak,
               "R2-16(i): ... and classifies as ScriptLeak");
    // The conjunction protects legit content: a quoted foreign title inside a
    // real Korean sentence (Han/Kana are in neither side) is not a third of the
    // text and never triples the length.
    TEST_CHECK(!IsUnexpectedScriptHeavyOutput(
                   L"그는 어젯밤 비가 내리는 동안 吾輩は猫である를 한 번에 읽었다.",
                   L"He read I Am a Cat in one sitting last night while the rain fell.", ko_mask),
               "R2-16(i): a quoted foreign title inside a translated sentence passes");
    // (ii) must NOT reject normal short answers and greetings.
    TEST_CHECK(!IsAmplifiedTinySourceOutput(L"좋습니다.", L"OK"),
               "R2-16(ii): 'OK' -> '좋습니다.' passes");
    TEST_CHECK(ClassifyTranslationOutput(L"좋습니다.", L"OK", "KO") == OutputRejectReason::None,
               "R2-16(ii): ... and classifies as accepted");
    TEST_CHECK(ClassifyTranslationOutput(L"안녕하세요!", L"Hi", "KO") == OutputRejectReason::None,
               "R2-16(ii): a normal short greeting passes");
    TEST_CHECK(ClassifyTranslationOutput(L"Hello, nice to meet you.", L"안녕", "EN") ==
                   OutputRejectReason::None,
               "R2-16(ii): a 22-code-point answer to a 2-code-point source passes");
    // Boundary pins for the two-tier guard (RC-2, v0.10.5): Tier 1 covers a
    // 1-4 code-point source answered with 32+ code points at a >= 10x ratio
    // (constants kAmplifiedTinyTier1OutputMinCodePoints/kAmplifiedTinyTier1Ratio
    // in translation_common.hpp, static_assert pins below); Tier 2 covers
    // 5..15 code points (or any single whitespace-free token) at 64+ / >= 6x.
    // The R3 "64 floor" comment is stale: the Tier-1 floor is now 32 with the
    // 10x ratio, so 63 vs the 4-code-point "OK!!" is rejected at 15.75x.
    TEST_CHECK(IsAmplifiedTinySourceOutput(std::wstring(64, L'a'), L"OK!!"),
               "RC-2 Tier1: source 4 / output 64 is rejected way above the ratio");
    TEST_CHECK(IsAmplifiedTinySourceOutput(std::wstring(63, L'a'), L"OK!!"),
               "RC-2 Tier1: output 63 >= 32 floor and >= 4*10 ratio, so it is rejected");
    // RC-2 Tier 2 (5..15 code-point source, or ANY single whitespace-free
    // token): 64+ output code points at a >= 6x ratio is an amplification
    // hallucination ("hello" -> a dictionary essay). Both directions pinned.
    TEST_CHECK(IsAmplifiedTinySourceOutput(std::wstring(100, L'a'), L"hello"),
               "RC-2 Tier2: a 100-code-point essay for 5-code-point 'hello' is rejected");
    TEST_CHECK(ClassifyTranslationOutput(std::wstring(100, L'a'), L"hello", "EN") ==
                   OutputRejectReason::ScriptLeak,
               "RC-2 Tier2: ... and classifies as ScriptLeak");
    TEST_CHECK(!IsAmplifiedTinySourceOutput(std::wstring(63, L'a'), L"hello"),
               "RC-2 Tier2: output 63 is below the 64 floor (allowed)");
    TEST_CHECK(!IsAmplifiedTinySourceOutput(std::wstring(100, L'a'),
                                            L"this is a normal length sentence"),
               "RC-2 Tier2: a spaced multi-word source over 15 cp is not a tiny source");
    // A single long whitespace-free token still counts as Tier-2 source
    // (20 cp * 6 = 120 <= 200).
    TEST_CHECK(IsAmplifiedTinySourceOutput(std::wstring(200, L'a'),
                                           L"internationalization"),
               "RC-2 Tier2: one long whitespace-free token is a Tier-2 source");
    TEST_CHECK(!IsAmplifiedTinySourceOutput(std::wstring(80, L'a'), L"ㅋㅋㅋㅋㅋ"),
               "R2-16(ii): a 5-code-point source is above the tiny-source bound");
    TEST_CHECK(!IsAmplifiedTinySourceOutput(std::wstring(80, L'a'), L""),
               "R2-16(ii): an empty source never trips the amplification rule");
    // R3 source-shape carve-out: a pure repetition source (laughter / emphasis)
    // is exempt - a chatty model's long laughter expansion is a legit answer.
    // RC-2 (v0.10.5): the repetition floor rose from 2 to >= 3 identical
    // blocks, so everyday reduplicated WORDS are no longer laugh-track
    // repetition. "hahaha" (3x "ha") stays in; the 2-char/4-char AA/ABAB
    // forms ("점점", "바이바이", "haha") moved to the negative pin below.
    TEST_CHECK(IsPureRepetitionSource(L"ㅋㅋㅋㅋ") && IsPureRepetitionSource(L"kkkk") &&
                   IsPureRepetitionSource(L"!!!!") && IsPureRepetitionSource(L"hahaha") &&
                   IsPureRepetitionSource(L"no no no") && IsPureRepetitionSource(L"k k k"),
               "R3(ii)+RC-2: one repeated unit ('ㅋㅋㅋㅋ', 'kkkk', 'hahaha', 'no no no') is a pure "
               "repetition source");
    // RC-2 non-laughter pins: 2-char AA and 4-char ABAB are ordinary words.
    TEST_CHECK(!IsPureRepetitionSource(L"점점") && !IsPureRepetitionSource(L"바이바이") &&
                   !IsPureRepetitionSource(L"haha"),
               "RC-2: AA/ABAB reduplicated words (점점/바이바이/haha) are NOT pure repetition sources");
    TEST_CHECK(!IsPureRepetitionSource(L"음") && !IsPureRepetitionSource(L"OK") &&
                   !IsPureRepetitionSource(L"hahah") && !IsPureRepetitionSource(L""),
               "R3(ii): the carve-out never covers the single-code-point residual or ordinary "
               "short sources");
    const std::wstring laughter_answer =
        L"Hahaha, that is so funny! I cannot stop laughing at that one, really!";
    TEST_CHECK(!IsAmplifiedTinySourceOutput(laughter_answer, L"ㅋㅋㅋㅋ"),
               "R3(ii): 'ㅋㅋㅋㅋ' -> a long laughter expansion passes (carve-out)");
    TEST_CHECK(ClassifyTranslationOutput(laughter_answer, L"ㅋㅋㅋㅋ", "EN") ==
                   OutputRejectReason::None,
               "R3(ii): ... and classifies as accepted");
    TEST_CHECK(IsAmplifiedTinySourceOutput(laughter_answer, L"음"),
               "R3(ii): the SAME answer to the single-code-point '음' is still rejected");
    TEST_CHECK(ClassifyTranslationOutput(laughter_answer, L"음", "EN") ==
                   OutputRejectReason::ScriptLeak,
               "R3(ii): ... and classifies as ScriptLeak");

    // ---- 261029_0001 FIX-D2: the carve-out is BOUNDED, not an exemption ----
    // The R3 draft exempted a pure-repetition source from rule (ii) entirely;
    // the rebuilt worker then answered "ㅎㅎㅎㅎ" / "kkkk" / "haha" with
    // 998 / 980 / 1110-code-point repeated-paragraph essays (1008 / 958 / 1122
    // UTF-8 bytes) delivered as status=ok (coder-report-fix-d §6). Under the
    // CEO ruling "언제나 잘 번역" that is nonsense output, not a translation. The
    // measured shape is a run of repeated paragraph blocks that is NOT a
    // consecutive token/line loop, so rules A/B/C pass it and rule (ii) is the
    // only gate that can reject it. A unique marker per pass keeps the tail out
    // of rule C.
    const wchar_t* const kRepetitionEssayTails[] = {
        L" First pass.",   L" Second pass.", L" Third pass.",  L" Fourth pass.",
        L" Fifth pass.",   L" Sixth pass.",  L" Seventh pass.", L" Eighth pass.",
    };
    std::wstring repetition_essay;
    for (const wchar_t* tail : kRepetitionEssayTails) {
        repetition_essay +=
            L"What a wonderful experience! I was so excited to see the results of my hard work "
            L"and efforts. I had a great time, and it was a very special moment for me.";
        repetition_essay += tail;
    }
    TEST_CHECK(CountCodePoints(repetition_essay) >= 1000,
               "FIX-D2: the witness essay is at least 1,000 code points (the measured live size)");
    TEST_CHECK(!OutputHasRepetition(repetition_essay, L"ㅋㅋㅋㅋ"),
               "FIX-D2: the witness essay is NOT a consecutive token/line loop (rules A/B/C "
               "pass it, so rule (ii) is the gate under test)");
    // RC-2: "hahaha" (3x "ha") keeps the historical repetition-source shape;
    // the old "haha" pin moved to the AA/ABAB negative pin above (4-char ABAB
    // is 2 blocks, below the >= 3 floor).
    TEST_CHECK(IsPureRepetitionSource(L"ㅋㅋㅋㅋ") && IsPureRepetitionSource(L"kkkk") &&
                   IsPureRepetitionSource(L"hahaha"),
               "FIX-D2+RC-2: the three measured laughter spellings are still repetition sources");
    TEST_CHECK(IsAmplifiedTinySourceOutput(repetition_essay, L"ㅋㅋㅋㅋ"),
               "FIX-D2: a 1,000-code-point essay for 'ㅋㅋㅋㅋ' trips rule (ii) again");
    TEST_CHECK(ClassifyTranslationOutput(repetition_essay, L"ㅋㅋㅋㅋ", "EN") ==
                   OutputRejectReason::ScriptLeak,
               "FIX-D2: 'ㅋㅋㅋㅋ' -> essay classifies as REJECTED (ScriptLeak)");
    TEST_CHECK(ClassifyTranslationOutput(repetition_essay, L"kkkk", "EN") ==
                   OutputRejectReason::ScriptLeak,
               "FIX-D2: 'kkkk' -> essay classifies as REJECTED (ScriptLeak)");
    TEST_CHECK(ClassifyTranslationOutput(repetition_essay, L"haha", "EN") ==
                   OutputRejectReason::ScriptLeak,
               "FIX-D2: 'haha' -> essay classifies as REJECTED (ScriptLeak)");
    // Ceiling boundary, inclusive like the 64 floor: 119 cp is still a
    // legitimate laughter expansion, 120 cp is an essay-scale answer.
    TEST_CHECK(!IsAmplifiedTinySourceOutput(std::wstring(119, L'a'), L"ㅋㅋㅋㅋ"),
               "FIX-D2: output 119 stays under the laughter ceiling (accepted)");
    TEST_CHECK(IsAmplifiedTinySourceOutput(std::wstring(120, L'a'), L"ㅋㅋㅋㅋ"),
               "FIX-D2: output 120 is the inclusive laughter ceiling (rejected)");
    // Short laughter answers are what the carve-out exists for - they pass.
    TEST_CHECK(ClassifyTranslationOutput(L"Hahaha!", L"ㅋㅋㅋㅋ", "EN") == OutputRejectReason::None,
               "FIX-D2: 'ㅋㅋㅋㅋ' -> 'Hahaha!' passes (a real laughter answer)");
    TEST_CHECK(ClassifyTranslationOutput(L"I'm dying laughing", L"ㅋㅋㅋㅋ", "EN") ==
                   OutputRejectReason::None,
               "FIX-D2: 'ㅋㅋㅋㅋ' -> 'I'm dying laughing' passes");
    // The reduplication controls keep their R2-6 Rule-B source guard (a
    // reduplication the user typed is content, never a loop).
    TEST_CHECK(!OutputHasRepetition(L"아니, 아니, 아니.", L"no no no") &&
                   ClassifyTranslationOutput(L"아니, 아니, 아니.", L"no no no", "KO") ==
                       OutputRejectReason::None,
               "FIX-D2: 'no no no' reduplication controls still pass (Rule B guard intact)");
    TEST_CHECK(!IsAmplifiedTinySourceOutput(std::wstring(100, L'a'), L"no no no"),
               "FIX-D2: a 100-code-point answer to 'no no no' stays under the ceiling");
    // The single-code-point residual is untouched: it is not a repetition, so
    // it keeps the 64-code-point floor.
    TEST_CHECK(IsAmplifiedTinySourceOutput(repetition_essay, L"음") &&
                   ClassifyTranslationOutput(repetition_essay, L"음", "EN") ==
                       OutputRejectReason::ScriptLeak,
               "FIX-D2: the '음' residual keeps the 64 floor and still rejects");
    static_assert(kAmplifiedRepetitionOutputMinCodePoints == 120,
                  "FIX-D2: the laughter ceiling for a pure-repetition source is 120 code points");
    // The share/expansion numbers themselves stay pinned to the header contract.
    static_assert(kUnexpectedScriptSharePercent == 30,
                  "R2-16: the unexpected-script share floor stays 30%");
    static_assert(kUnexpectedScriptLengthExpansionPercent == 300,
                  "R2-16: the length-expansion gate stays > 3x");
    static_assert(kAmplifiedSourceMaxCodePoints == 4 && kAmplifiedOutputMinCodePoints == 64,
                  "R3: the tiny-source amplification pair is 4 -> 64 code points");

    // ---- Structural pins: the production wiring matches the contract ----
    const std::filesystem::path tc_path =
        ResolveRepoFile(L"src\\engine_core\\translation_common.cpp");
    TEST_CHECK(!tc_path.empty(), "R1-1: translation_common.cpp resolvable for the wiring pins");
    if (!tc_path.empty()) {
        std::ifstream in(tc_path, std::ios::binary);
        std::stringstream ss;
        ss << in.rdbuf();
        const std::string src = ss.str();
        auto count_occurrences = [](const std::string& hay, const std::string& needle) {
            size_t count = 0;
            size_t pos = 0;
            while ((pos = hay.find(needle, pos)) != std::string::npos) {
                ++count;
                pos += needle.size();
            }
            return count;
        };

        // R1-2: the greedy leg is the pure decision + a penalties->greedy chain.
        TEST_CHECK(src.find("switch (DecideSamplerShape(temperature, rep_pen))") != std::string::npos,
                   "R1-2: the sampler branch is driven by DecideSamplerShape");
        TEST_CHECK(src.find("llama_sampler_chain_add(smpl, llama_sampler_init_penalties(kPenaltyLastN, rep_pen, 0.0f, 0.0f));\n"
                            "            llama_sampler_chain_add(smpl, llama_sampler_init_greedy());") != std::string::npos,
                   "R1-2: the penalized greedy chain adds penalties FIRST and greedy LAST");
        TEST_CHECK(src.find("smpl = llama_sampler_init_greedy();") != std::string::npos,
                   "R1-2: the bare greedy allocation survives for rep_pen <= 1.0 (byte-identical)");
        {
            const size_t greedy_case = src.find("case SamplerShape::PenalizedGreedy");
            const size_t dist_case = src.find("case SamplerShape::Dist");
            TEST_CHECK(greedy_case != std::string::npos && dist_case != std::string::npos &&
                           greedy_case < dist_case,
                       "R1-2: the penalized-greedy case exists and precedes the sampled case");
            if (greedy_case != std::string::npos && dist_case != std::string::npos &&
                greedy_case < dist_case) {
                const std::string greedy_body = src.substr(greedy_case, dist_case - greedy_case);
                TEST_CHECK(greedy_body.find("llama_sampler_init_greedy") != std::string::npos,
                           "R1-2: the greedy case still ends on the greedy sampler");
                TEST_CHECK(greedy_body.find("llama_sampler_init_top_k") == std::string::npos &&
                               greedy_body.find("llama_sampler_init_top_p") == std::string::npos,
                           "R1-2: top_k/top_p stay out of the greedy chain (argmax-invariant)");
            }
        }

        // R1-1: the gate runs on BOTH rungs (rung-1 acceptance + rung-2 final).
        TEST_CHECK(count_occurrences(
                       src, "ClassifyTranslationOutput(ToUtf16(trimmed_u8), cur, tgt_code)") == 2,
                   "R1-1: the gate is applied to BOTH rungs' trimmed output");
        TEST_CHECK(src.find("ENGINE/Translate/038") != std::string::npos,
                   "R1-1: the rung-2 rejection has its own shape-only diagnostic (038)");
        TEST_CHECK(src.find("ENGINE/Translate/039") != std::string::npos,
                   "R1-1: the mid-decode repetition abort has its own shape-only diagnostic (039)");
        TEST_CHECK(src.find("rung2_repetition_aborted") != std::string::npos &&
                       src.find("rung1_aborted_repetition") != std::string::npos,
                   "R1-1: both rungs track a repetition abort");
        {
            const size_t idx_reject = src.find("ENGINE/Translate/038");
            const size_t idx_accept = src.find("ENGINE/Translate/035");
            TEST_CHECK(idx_reject != std::string::npos && idx_accept != std::string::npos &&
                           idx_reject < idx_accept,
                       "R1-1: a rung-2 rejection answers std::nullopt BEFORE the accept log "
                       "(honest engine_failed, never garbage)");
        }
        // The mid-decode probe runs on BOTH rungs; the old rung-1-only guard
        // (`!completion_form &&` in front of the cadence) must be gone.
        TEST_CHECK(src.find("!completion_form && (i + 1) % kEchoPrefixProbeTokenCadence") ==
                       std::string::npos,
                   "R1-1: the periodic probe is no longer rung-1 only");
        TEST_CHECK(src.find("(i + 1) % kEchoPrefixProbeTokenCadence == 0 && !output_u8.empty()") !=
                       std::string::npos,
                   "R1-1: the probe fires on both rungs at the existing cadence");
        TEST_CHECK(src.find("if (OutputHasRepetition(ToUtf16(output_u8), cur))") != std::string::npos,
                   "R1-1/R2-6: the mid-decode probe uses the SAME predicate AND source evidence as "
                   "the post-decode gate");

        // R2-6: the calibrated envelope is code, not only a comment.
        TEST_CHECK(src.find("kRepeatedTokenRunMinCoveragePercent") != std::string::npos &&
                       src.find("HasIdenticalTokenRun(source, kRepeatedTokenRunMinCount)") !=
                           std::string::npos,
                   "R2-6: Rule B carries the span floor AND the source reduplication guard");
        TEST_CHECK(src.find("if (lines[i] == lines[i - 1])") != std::string::npos,
                   "R2-6: Rule A compares ADJACENT lines (consecutive-only)");
        TEST_CHECK(src.find("lines[j] == lines[i] && ++count >= kRepeatedLineMinCount") ==
                       std::string::npos,
                   "R2-6: the pre-fix non-consecutive line count is gone");

        // R2-7: the translated-label guard is line-indexed in the gate.
        TEST_CHECK(src.find("LineStartsWithColonLabel(source_lines[i])") != std::string::npos,
                   "R2-7: a colon-label needle is exempted by the SOURCE line at the same index");

        // R2-8: the stitched whole is re-gated before the chunked path returns.
        {
            const size_t stitch_pos = src.find("stitched += chunk_trailing_separators[k];");
            const size_t regate_pos = src.find("if (OutputHasRepetition(stitched, src_w))");
            const size_t return_pos =
                regate_pos == std::string::npos
                    ? std::string::npos
                    : src.find("return stitched;", regate_pos);
            TEST_CHECK(stitch_pos != std::string::npos && regate_pos != std::string::npos &&
                           stitch_pos < regate_pos && return_pos != std::string::npos,
                       "R2-8: the repeated-whole gate runs AFTER stitching and BEFORE the return");
            TEST_CHECK(src.find("ENGINE/Translate/041") != std::string::npos,
                       "R2-8: the stitched-whole rejection has its own shape-only diagnostic (041)");
        }

        // R2-16: the fourth rule is wired into the single gate used by both rungs.
        TEST_CHECK(src.find("IsUnexpectedScriptHeavyOutput(output, source, TargetScriptClasses(tgt_code))") !=
                           std::string::npos &&
                       src.find("IsAmplifiedTinySourceOutput(output, source)") != std::string::npos,
                   "R2-16: both calibrated shapes are wired into ClassifyTranslationOutput");

        // Model-agnostic pin: the leakage table carries no model/token names.
        {
            const size_t table_begin = src.find("kMetaLeakageNeedles[] = {");
            const size_t table_end =
                table_begin == std::string::npos ? std::string::npos : src.find("};", table_begin);
            TEST_CHECK(table_begin != std::string::npos && table_end != std::string::npos,
                       "R1-1: the meta-leakage table is a single literal table");
            if (table_begin != std::string::npos && table_end != std::string::npos) {
                const std::string table = src.substr(table_begin, table_end - table_begin);
                TEST_CHECK(table.find("hymt") == std::string::npos &&
                               table.find("Hy-MT2") == std::string::npos &&
                               table.find("MiLM") == std::string::npos &&
                               table.find("llama") == std::string::npos,
                           "R1-1: the leakage table is model-agnostic (no model/token names)");
            }
        }
    }

    // ---- R2-10 (261029_0001): the documentation-drift cluster ----
    // Each of these comments told a reader something the code does not do (the
    // contract literal a consumer keys on, a symbol name that does not exist, a
    // pointer to docs that moved, a claim about the drag path that FIX-B2
    // changed). Prose alone drifts again, so the fixed statements are pinned.
    {
        auto read_repo_src = [](const wchar_t* rel, std::string& out) -> bool {
            const std::filesystem::path p = ResolveRepoFile(rel);
            if (p.empty()) {
                return false;
            }
            std::ifstream in(p, std::ios::binary);
            out.assign((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
            return !out.empty();
        };
        std::string client_h;
        std::string verify_h;
        std::string helpers_h;
        std::string input_h;
        std::string readme_md;
        if (!read_repo_src(L"src\\engine_host_client.hpp", client_h) ||
            !read_repo_src(L"src\\model_verify_sample.hpp", verify_h) ||
            !read_repo_src(L"src\\engine_core\\engine_core_helpers.hpp", helpers_h) ||
            !read_repo_src(L"src\\win32_input.hpp", input_h) ||
            !read_repo_src(L"README.md", readme_md)) {
            std::cout << "[SKIP] R2-10 doc pins: a boundary file is not resolvable from the "
                         "test CWD." << std::endl;
        } else {
            TEST_CHECK(client_h.find("err=\"connect:<oserr>\"") != std::string::npos,
                       "R2-10: the client contract documents the token the client EMITS "
                       "(connect:<oserr>)");
            TEST_CHECK(client_h.find("MIRROR DUTY") != std::string::npos,
                       "R2-10: the contract names the sibling-workspace mirror duty");
            TEST_CHECK(verify_h.find("ComputeFileSampleSha256") == std::string::npos &&
                           verify_h.find("ComputeSampleSha256") != std::string::npos,
                       "R2-10: model_verify_sample.hpp names the symbol that exists");
            TEST_CHECK(helpers_h.find("src/model_verify_sample.hpp") != std::string::npos,
                       "R2-10: the marker doc pointer resolves to model_verify_sample.hpp");
            TEST_CHECK(input_h.find("the DRAG path installs its own scope too") != std::string::npos,
                       "R2-10: the clipboard comment matches FIX-B2 (drag path HAS a scope)");
            TEST_CHECK(readme_md.find("measured AFTER the paste") != std::string::npos,
                       "R2-10: the README settle delay is described in the implemented order");
            TEST_CHECK(readme_md.find("are **advisory**") != std::string::npos,
                       "R2-10: the README discloses that the exclusion tags are advisory");
            TEST_CHECK(readme_md.find("does sit on the system clipboard") != std::string::npos,
                       "R2-10: the README discloses the bounded clipboard exposure window");
        }
    }

    if (g_failed_count == failures_before) {
        std::cout << "[PASS] R1-1 output gate + R1-2 sampler shape (261029_0001) passed."
                  << std::endl;
    } else {
        std::cout << "[FAIL] R1-1/R1-2 suite: " << (g_failed_count - failures_before)
                  << " check(s) failed." << std::endl;
    }
}

// B3 fix (session 260928_0001): per-family worker single-instance mutex pins —
// the wp::MutexNameForFamily derivation contract (legacy exact / distinct
